/* ============================================================
   新增边批次B：为 nodes_soc / nodes_econ / nodes_psy / nodes_pol / nodes_exi
   末尾孤儿节点补的类型化边 + 矩阵格补录
   边字段：f=源 t=目标 type∈{genealogy,coupling,tension,produces,operationalizes}
   label≤8字 m=机制说明(150-230字简体中文) ev∈{emp,obs,fw,nat,spec} s∈{1,2,3}
   ============================================================ */
window.DB_NEW_EDGES_B = [
/* ══ 经济学 econ ══ */
{f:"mincer",t:"modigliani_lc",type:"coupling",label:"剖面×平滑",m:"明塞尔的收入函数回答工资剖面为何是凹的——经验回报递减使劳动收入中年见顶；莫迪利安尼回答的是在这条剖面上理性人怎么花：把一生收入折现成总资源再平滑分摊，青年借、中年存、老年耗。一个供出收入曲线、一个给出消费策略，跨期优化的供需两半在生命历程轴上互为镜像——生涯格的财务行为可预测为「剖面位置×平滑能力」的函数。",ev:"fw",s:2},
{f:"friedman_pi",t:"modigliani_lc",type:"coupling",label:"平滑双子",m:"跨期平滑思想的两个切法：弗里德曼按可预期性切——消费锚定持久收入、暂时波动被存贷缓冲；莫迪利安尼按生命阶段切——消费锚定一生总资源、储蓄率随年龄驼峰起落。两者都向「当期收入决定消费」的凯恩斯直觉开战，也都预设同一个关键条件：家户借得到也存得下——这个前提的阶级分布恰是矩阵要量的东西。两假说后来在消费函数文献里长期共享同一组检验数据。",ev:"fw",s:2},
{f:"present_bias",t:"modigliani_lc",type:"tension",label:"平滑vs短视",m:"生命周期假说需要人能执行几十年期的储蓄计划；现时偏向证明人的折扣函数是双曲的——近期诱惑被系统性高估，自控失败使驼峰储蓄剖面无法兑现。实证上退休储蓄不足与401k自动登记的惊人效力都说明「理性平滑」不是描述是愿望：模型给规范基准、偏差研究给为何人人做不到——两条文献在「储蓄为何不足」上正负对读。自控失败让退休账户的低积累成为常态而非例外。",ev:"emp",s:2},
{f:"friedman_pi",t:"standing",type:"coupling",label:"暂时成常态",m:"弗里德曼把收入劈成持久与暂时两半，暂时成分靠储蓄与借贷缓冲——前提是波动围绕稳定趋势。不稳定无产者的处境是把这个前提拆掉：零工与短约让收入几乎全是「暂时成分」，没有持久锚可以回归，缓冲装置又恰恰按阶级缺席。弗里德曼给波动命名，斯坦丁记录波动变成常态的人群——「收入波动」从技术概念升格为阶级位置。斯坦丁笔下「危险的阶级」正是这条边的人口。",ev:"fw",s:2},
{f:"friedman_pi",t:"conger",type:"coupling",label:"压力=波动",m:"家庭压力模型的自变量是「经济压力」——一个含混总称；持久收入假说给了它精确的微观定义：伤害家庭的是暂时收入的负向冲击，因为信贷约束家庭无法把它平滑掉，冲击直接穿透为父母情绪与教养质量。一个给波动的分解、一个给波动的下游通路——康格链条上「经济压力→父母抑郁」的第一环，正是无法被缓冲的暂时成分。Elder大萧条研究的父职受损链是同一通路的最早证据。",ev:"fw",s:2},
{f:"friedman_pi",t:"scarcity",type:"tension",label:"平滑假定",m:"持久收入假说的隐含承诺：理性家户能把暂时波动平滑掉，所以截面贫困被高估。稀缺认知税给出反证：恰恰是无法平滑的人在承受带宽税——稀缺的认知占用随波动起舞，贫困本身制造更多决策失误。若平滑机制真在运转，带宽就不该随收入起伏——「穷人无法平滑」这一事实本身才是问题，平滑假设是它要解释的失败。这条张力是全图「谁拥有跨期能力」问题的经济端。",ev:"emp",s:3},
{f:"veblen",t:"duesenberry",type:"genealogy",label:"炫耀→棘轮",m:"凡勃伦的炫耀性消费是社会学寓言：上层消费给下层立下必须仰视的标准。杜森贝里把寓言改写成可检验的储蓄方程：效用依赖相对位置＋消费不可逆——示范效应让低收入家庭压缩储蓄追赶，消费标准沿阶层向下传染。谱系关系直白：有闲阶级论给出机制的画面，相对收入假说给它装上参数——位置消费的微观起点在此。从《有闲阶级论》到这本小册子正好五十年。",ev:"fw",s:2},
{f:"duesenberry",t:"thurow",type:"coupling",label:"排位结构",m:"杜森贝里公理说绝对篮子无效、只看相对位置；瑟罗的工作队列把同一结构搬进劳动市场——工资不取决于技能存量而取决于你在队里的位置，教育只是排队号码牌。两个理论共享「位置商品」逻辑：绝对量增长不解决排序问题，水涨船高的参照系吞掉全部进步——消费维与就业维是一对同构的排位竞赛。弗兰克的位置外部性文献是这对边的当代复兴。",ev:"fw",s:3},
{f:"duesenberry",t:"prospect",type:"genealogy",label:"参照点前史",m:"相对收入假说的两条公理——效用是相对的、损失比等量收益更痛（棘轮效应中死守已达标消费）——正是前景理论参照点依赖与损失厌恶的消费版预演，早了整整三十年。卡尼曼把参照点放进认知心理学给出可实验的偏差结构，杜森贝里版本留在宏观消费函数里没被认领；两者在「效用无绝对锚」上同源——参照系不是背景而是自变量。",ev:"fw",s:2},
{f:"duesenberry",t:"easterlin",type:"genealogy",label:"相对→幸福",m:"杜森贝里1949年写下「效用是相对的」时只用于解释储蓄方程；伊斯特林1974年把同一公理推到主观福祉全域：幸福锚定相对收入与社会比较，水涨船高时绝对进步被参照系整体吞没——于是GDP翻倍、幸福原地踏步。一个预言消费追赶没有终点，一个证明追赶在幸福账户上同样零和——参照点内生是两条文献共用的引擎。斯蒂文森与沃尔夫斯的挑战仍未拆掉参照系这台引擎。",ev:"emp",s:3},
{f:"easterlin",t:"thurow",type:"coupling",label:"排序零和",m:"伊斯特林悖论是排序经济的幸福审计报告：若福祉按排位计分，增长就是零和军备——人人收入翻倍、排位纹丝不动。工作队列模型在劳动市场端给出同一结构：教育扩张不改变岗位排序、只抬高门槛。一个是宏观幸福数据、一个是就业排队模型，在「位置性竞争使绝对进步失效」上互证——悖论不是测量事故而是排位制度的会计结果。日本高速成长期幸福感停滞是这条边的跨国注脚。",ev:"fw",s:3},
{f:"easterlin",t:"scarcity",type:"coupling",label:"门槛分界",m:"伊斯特林悖论只管门槛以上：超过基本线后钱不再买幸福。稀缺认知税管的是门槛以下：基本线之下钱非常要紧——带宽被生存占用、认知税随稀缺计价。两条文献拼出收入-幸福关系的完整地形：底端是带宽税的陡峭坡、顶端是参照系吞没的平顶——「钱能不能买幸福」取决于站在曲线哪一段，而那段位置是阶级给的。分界点大约在基本需求被覆盖处，恰是阶级轴。",ev:"emp",s:3},
{f:"akerlof_lemons",t:"spence",type:"coupling",label:"问题×卖方解",m:"柠檬市场讲信息不对称如何杀死交易：买方按平均质量出价→好车退出→螺旋崩塌。斯宾塞的信号理论给出卖方解法：高质量者用高成本信号（文凭、质保）把自己与柠檬分开——信号贵到假货跟不起才有效。一个讲市场为何失灵、一个讲失灵后的自救装置，诺贝尔委员会把两者打包授奖正因为它们是一枚硬币的两面：文凭军备赛的根目录在这对边上。",ev:"fw",s:3},
{f:"akerlof_lemons",t:"arrow_stiglitz",type:"coupling",label:"问题×买方解",m:"信息不对称三角的第三角：柠檬是问题，信号是卖方自救，筛选是买方反攻——雇主与保险公司主动设计识别装置（考试、试用期、免赔额）把隐藏质量逼出来。阿克洛夫证明看不见质量的市场会萎缩，阿罗-斯蒂格利茨证明买方不会坐等、会造工具去看。文凭、背调、实习考察期都是筛选机制的实例：不对称信息家族的完整三角在此合拢。",ev:"fw",s:3},
{f:"akerlof_lemons",t:"rivera",type:"coupling",label:"看不透→看出身",m:"柠檬定价的逻辑：看不透质量就按群体均值出价。里维拉的精英招聘民族志是同一逻辑的白领版——雇主看不透真实生产力，就用出身代理：名校、谈吐、「文化匹配」这些被当成才能评估的东西，本质是柠檬市场上的质量代理变量。一边是二手车市场的螺旋崩塌、一边是投行面试的fit筛选——看不透就按标签定价，是信息不对称的通用解法。",ev:"fw",s:2},
{f:"akerlof_lemons",t:"stat_discrim",type:"genealogy",label:"个体→群体",m:"柠檬市场处理个体质量不可观测；统计歧视把同一信息结构推到群体维度：既然个体生产力看不见，就拿群体均值当代理——某群体信号噪声大，每个成员都被按均值折价。菲尔普斯与阿罗的模型是柠檬逻辑的系谱性延伸：不对称信息不消失，只是从「这台车好不好」换成「这群人平均水平」——个体优秀追不回群体定价。自我实现机制让均值定价一旦被写成就自我续命。",ev:"fw",s:3},
{f:"stat_discrim",t:"dual_labor",type:"produces",label:"代理→分割",m:"二元劳动市场问的是：一级部门的好工作入口由谁把守？统计歧视给出生成机制之一：当个体生产力不可观测，入口筛选必然诉诸群体代理——性别、族裔、阶级的均值定价在关口完成分割，被折价群体系统性流入次级部门。歧视在此不是态度而是信息约束下的均衡——一级部门的高监督成本与低替换意愿，放大了按均值定价的诱惑，分割因此自我维持。",ev:"fw",s:2},
{f:"stat_discrim",t:"human_capital",type:"tension",label:"同技不同价",m:"人力资本模型的核心等式是工资≈边际生产力≈技能存量；统计歧视直接拆台：同等技能因群体标签被系统性折价，「技能决定工资」在均衡里不成立——且折价自我实现，预期被歧视的群体减少技能投资，偏见变成事实。一边宣称市场奖励能力，一边证明市场在信息约束下奖励标签——这不是异常值而是最优反应的产出。审计实验里同履历不同回报是这条张力最直接的数据。",ev:"emp",s:3},
{f:"stat_discrim",t:"correll",type:"coupling",label:"两味歧视",m:"统计歧视说偏见是信息约束下的最优反应、无恶意也产生；科雷尔的母职惩罚审计实验证明品味成分并未消失——同等履历只改「母亲」一栏，回电率与起薪齐降。两份文献的分工：审计设计能把统计与品味成分在同一份雇佣决策里半分离，实证结论是两机制共存难分解——「她可能请假多」的均值定价与「母亲不该拼」的偏好，在同一张简历上叠加。",ev:"emp",s:3},
{f:"becker_time",t:"lareau",type:"coupling",label:"日程=高投入",m:"贝克尔把家庭写成小工厂：效用由市场品加自有时间生产，时间投入按影子价格配置。拉鲁拍下的中产协作培养正是这个生产函数的高投入解——排满的日程表、说理协商、机构操作示范，是密集型时间投入换儿童人力资本的技术路线；自然成长则是低货币高替代时间的另一解。一个给投入产出的账簿、一个给账簿的民族志细节——日程表就是生产函数被看见的形态。",ev:"fw",s:3},
{f:"becker_time",t:"hochschild",type:"tension",label:"分工≠权力",m:"贝克尔的时间分配说家务分工是效率问题：市场工资低的一方多承担家务，影子价格定一切。第二轮班揭示这笔账漏了什么：女性下班后再上八小时无酬班，不是影子价格的合理分配而是性别权力在时间上的兑现——「谁的时间更值钱」的预设早已内含不平等。家庭生产模型把无酬劳动自然化，霍克希尔德把它重新问题化：分工表背后是支配结构。",ev:"fw",s:3},
{f:"becker_time",t:"hays",type:"produces",label:"投入被抬价",m:"贝克尔的框架里，育儿投入是由影子价格与预期回报决定的优化变量；海斯的密集母职展示这个变量的当代形态：母职的时间与情感投入标准被文化持续抬高，超过任何可计回报的临界点——投入要求不再由优化逻辑而是由意识形态供给。家庭生产函数给出「投入多少」的问题结构，密集母职给出「投入标准为何无限膨胀」的答案——理性框架撞上文化抬价。",ev:"fw",s:2},
{f:"solow_growth",t:"human_capital",type:"produces",label:"残差→教育",m:"索洛残差是增长核算里吞不掉的那八分之七——资本与劳动解释不了的人均产出增长。这个「对无知的度量」直接催生人力资本议程：舒尔茨与贝克尔把残差拆解为教育、健康与在职训练的投资回报——若技术进步的载体是人，增长之谜就改写成技能形成问题。残差先是承认无知，人力资本把承认变成产业：教育经济学整条产品线从这个残差里长出来。",ev:"fw",s:3},
{f:"solow_growth",t:"heckman_skill",type:"coupling",label:"残差→投入",m:"索洛模型对增长的解释停在「技术」这个黑箱上；赫克曼的技能形成技术把黑箱打开一层：技能不是外生禀赋而是投入函数——早期投入、动态互补、认知与非认知分轨生产。一个说增长全靠我们不懂的东西，一个说那东西部分是可投资的技能存量——残差之谜被翻译成生命历程问题：哪个阶段投、投给谁，决定残差能在哪兑现。Heckman的动态互补给了残差一张投入产出解剖图。",ev:"fw",s:2},
{f:"schumpeter",t:"solow_growth",type:"coupling",label:"残差的引擎",m:"索洛残差标出增长的未知源头却拒绝命名它；熊彼特早二十年已给出微观引擎：企业家的创新——新产品、新工艺、新组织——以创造性破坏推动产出，模仿扩散摊薄租金、下一波再破坏。阿吉翁-豪伊特后来把两框架焊接为内生增长理论：残差不再是无知的度量而是创新活动的统计影子。一个给增长的黑箱、一个给黑箱里的发动机。内生增长理论（Romer一路）是这对边的正式焊接点。",ev:"fw",s:2},
{f:"schumpeter",t:"sbtc_polar",type:"produces",label:"破坏的任务解剖",m:"创造性破坏讲产业版图的风暴：旧结构被新技术连根拔起。SBTC文献把风暴落到任务层解剖：被替代的不是「工人」而是「例行任务」——认知非常规被补充、体力非常规被留下，劳动市场两极空心化。熊彼特给宏观叙事「创新吞掉旧位置」，任务模型给具体清单「哪些任务先被吃」——创造性破坏在生涯层显出真身：消失的是中段技能需求。",ev:"emp",s:3},
{f:"schumpeter",t:"kalleberg",type:"produces",label:"破坏→坏工作",m:"创造性破坏的标准叙事颂扬创造面；卡利贝格的好工作坏工作记录破坏面的生涯代价：消失的中段职位不是被「升级」而是被分化——一端是稳定契约的好工作、一端是不稳无保障的坏工作。熊彼特说结构换新，卡利贝格问旧结构里的人去哪——中年技能存量被一笔勾销、再就业难，是破坏在个体生命历程上的记账方式。破坏面与创造面的时间差在叙事里常被美化，矩阵必须补记。",ev:"fw",s:2},
{f:"coase",t:"dual_labor",type:"coupling",label:"企业=分割源",m:"科斯问「市场有效为何有企业」：交易有成本，行政命令比逐次签约便宜时企业就出现。这个答案顺手解释了二元劳动市场的半边结构：内部劳动市场、晋升阶梯、行政定薪都是企业边界的产物——一级部门的岗位之所以是「内部货」，正因为市场交易成本把用工关系圈进了组织围墙。交易成本给企业的存在理由，二元市场给这个理由的分层后果。",ev:"fw",s:2},
{f:"coase",t:"north",type:"genealogy",label:"成本→制度",m:"科斯定理的真正教益是其反面：交易成本从非零，所以产权界定、法律与制度长什么样才是真实世界的主角。诺思把这个反面扩成整个研究纲领——制度即博弈规则，存在的理由正是降低交易成本与不确定性；路径依赖与非正式约束的惰性，解释了为何规则移植常失灵。新制度经济学的出生证是科斯签发的：先证明谈判不免费，才轮得到制度上场。",ev:"fw",s:3},
{f:"north",t:"gatsby",type:"coupling",label:"流动靠制度",m:"盖茨比曲线抛出跨国谜题：同样程度的不平等，各国代际流动性迥异。诺思的框架给了谜底方向：差异多半不在市场而在制度安排——学校怎么分流、劳动市场怎么准入、产权与社会保护怎么写。正式规则可速改、非正式约束惰性长，解释了为何有些国家改不动：流动性的高低是被制度锁住的历史产物，不是经济增长的自动赠品。Corak的跨国比较证明流动性差异远超测量误差。",ev:"fw",s:2},
{f:"north",t:"kohli_mayer",type:"coupling",label:"规则→人生",m:"诺思说制度是博弈规则：教育法、劳动法、养老金把行动空间结构化。科利把同一思路落到生涯层：生命历程被制度硬编码成教育-工作-退休的三段式——学校龄、退休年龄、缴费年限这些「规则」把人生变成可治理的序列。一个讲制度如何框住社会博弈、一个讲制度如何框住整条人生——生命历程制度化就是诺思逻辑在时间维的应用。",ev:"fw",s:3},
{f:"north",t:"acemoglu_robinson",type:"genealogy",label:"谁定制度",m:"诺思证明制度重要且路径依赖，却没回答政治问题：低效制度为何被选择、谁来选择？阿西莫格鲁与罗宾逊补上分配冲突的政治学——攫取制度锁死是因为受益者掌枪，包容制度运转是因为它威胁不了权力。谱系关系明确：制度变迁理论的政治化续章，从「制度如何演化」推进到「谁决定制度往哪演化」——国富国穷的分水岭被写成权力分配问题。",ev:"fw",s:3},
{f:"acemoglu_robinson",t:"schumpeter",type:"coupling",label:"怕破坏=攫取",m:"熊彼特的创造性破坏是增长引擎，但引擎要烧掉在位者的位置——这正是攫取性制度恐惧它的原因：精英宁可压制创新也要保住抽取结构；包容性制度则把破坏转化为增长，因为输家有政治声音、赢家不能永远收租。A&R给创造性破坏加上政治条件：创新能不能发生，先看制度容不容得下破坏——技术问题背后是分配问题。《国家为什么会失败》把这条耦合写成了全球史叙事。",ev:"fw",s:3},
{f:"acemoglu_robinson",t:"human_capital",type:"tension",label:"制度>技能",m:"人力资本叙事把国富国穷读成技能存量之差：穷国缺教育。A&R用殖民地工具变量给出相反数量级：制度类型可解释前殖民地间约四分之三的收入差距——同样的技能在攫取制度下无处兑现，边界两边同质人口产出天壤之别。这不是否定教育价值，而是重排因果层级：技能回报的结构本身就是制度产物——人力资本的「因」先被制度写死。",ev:"emp",s:2},
{f:"simon_bounded",t:"ostrom",type:"coupling",label:"为真人设计",m:"西蒙的有限理性说人不是全知计算器：认知带宽、信息、时间全受限。奥斯特罗姆的设计原则正是按这个真人规格做制度工程——规则贴合当地条件（不必全知全局）、使用者互相监督（分散认知负担）、渐进式制裁（低成本纠错）、在地冲突解决（不外包给遥远的法院）。公地治理不靠利维坦也不靠完美计算：互惠规范就是有限理性的制度补丁。",ev:"fw",s:2},
{f:"ostrom",t:"putnam",type:"tension",label:"信任可制造",m:"帕特南的社会资本叙事带悲观底色：信任是慢变量文化遗产，衰落了就很难再造。奥斯特罗姆的设计原则给出工程乐观主义的反驳：边界清晰、参与制定、自我监督、渐进制裁的架构能在田野里生产出信任——菲律宾灌溉社群的自治是造出来的不是祖传的。一个说社会资本只能消耗、一个说它可以被制度生产——衰落曲线并非不可违逆的熵。",ev:"emp",s:2},
{f:"ostrom",t:"scott_moral",type:"coupling",label:"在地规则智慧",m:"斯科特的道义经济记录东南亚农民社群自有的规范秩序——生存伦理、互惠惯例、弱者武器。奥斯特罗姆的公共池研究是同一种田野精神的水利版：在地社群反复演化出可持续的自我治理，设计原则不是外部蓝图而是从幸存案例里归纳的土办法。两者共享一个判断：底层社群的规则智慧系统性被低估——「无力自组织」的假定本身就是位置偏见。",ev:"fw",s:2},
{f:"banerjee_duflo",t:"bertrand_pov",type:"coupling",label:"RCT×行为观",m:"行为贫困观提出第三种立场：穷人不是更理性也不是更愚昧，而是同样偏差、余量更窄。班纳吉与迪弗洛的RCT纲领给这个立场系统田野基础：逐项实验显示不买最便宜热量买口味、不储蓄因无金融产品可用——看似非理性的选择多是约束下的合理反应。实验证据把「偏差相同、预算更紧」从命题变成可量目录：该修的是约束不是人。Bertrand等的「行为+约束」第三立场在此被系统实证化。",ev:"emp",s:3},
{f:"banerjee_duflo",t:"scarcity",type:"coupling",label:"约束下的理性",m:"稀缺认知税说贫困占用带宽→决策质量下降，方向是从认知到贫困；贫穷经济学的RCT证据提供边界修正：许多「认知失误」其实是环境与制度的合理反应——没有银行账户的人不储蓄不是短视。两条文献互为校准：带宽税是真的、但比主张的窄——田野逐项检验把「稀缺致误」与「环境致误」在同一张决策清单上分开记账。两阵营的数据在储蓄、健康、教育多个市场上互校。",ev:"emp",s:3},
{f:"banerjee_duflo",t:"lewis_poverty",type:"tension",label:"逐条反驳文化",m:"刘易斯的贫困文化说穷人世代传递一套自我延续的价值与行为模式——文化本身是囚笼。《贫穷经济学》几乎逐条反驳：穷人在约束下的选择相当理性，差异出在选项集不在偏好——不储蓄是因无产品、不驱虫是因价格门槛、不投保是因无保险可买。结构决定论与文化决定论的百年对垒在此收到实验裁决：换约束不换「文化」，行为立刻变。",ev:"emp",s:3},
{f:"banerjee_duflo",t:"perry_abc",type:"coupling",label:"同源实验法",m:"Perry与Abecedarian是发达国家的早期干预RCT：高成本幼教投入换长期回报；J-PAL是全球南方版：驱虫、校餐、教师打卡逐项做随机对照。方法完全同源——把大问题切成可检验的小问题、用实验识别因果、拿折现算成本效益。一边证明早期投入回报率超市场、一边证明小干预有因果效力——「贫困陷阱需逐个证明」是两者共享的实证纪律。",ev:"emp",s:2},
{f:"smeeding",t:"gatsby",type:"operationalizes",label:"曲线的底座",m:"盖茨比曲线画不平等与流动性的跨国负相关，但曲线可信度取决于底层数据口径——LIS自1983年把数十国家户调查做统一的「LIS化」处理，Corak的跨国流动性比较正搭在这个数据底座上。斯米丁的分解更给出机制读数：各国市场贫困差距不大、拉开距离的是转移支付的拉平力度——曲线背后是政策选择而非市场宿命，测量学把制度差异变成可见数字。",ev:"emp",s:3},
{f:"smeeding",t:"saez_zucman",type:"coupling",label:"底端×顶端",m:"两套测量工程分管分布两端：LIS家户调查管中下层——贫困率、转移效应、跨国可比；Saez与Zucman的资本化法管顶端——税务数据重建顶层份额，补上调查抓不住的富人。方法论互补校验：调查法的顶端盲区恰是资本化法的辖区，税务数据的底层噪声由调查补上——不平等的全光谱需要两套仪器拼合，任何单测度都自带阶级盲区。",ev:"emp",s:2},
{f:"smeeding",t:"diverging",type:"coupling",label:"分岔是政策",m:"麦克拉纳汉的分岔命运记录美国两条阶级轨道：一边母亲高学历晚育稳定、一边早育单亲高流动。LIS框架把这个美国故事放进跨国对照：同样的家庭结构变迁，北欧的政策拉平力度使分岔远没那么深——分岔是政策放大的而非人口学的必然。一个民族志级的轨迹记录、一个跨国测量底座，合起来把「美国例外」翻译成「制度选择」：别国也变了家庭，只是没让它分岔。",ev:"emp",s:2},
{f:"piketty",t:"milanovic",type:"coupling",label:"国内→全球",m:"皮凯蒂的r>g是一国之内资本集中的引力定律；米兰诺维奇把坐标系放大到全球公民之间：按全球收入百分位排，1988-2008的增长呈大象曲线——亚非新兴中产与顶端1%大涨、富国中下层近零。一个测国家内的纵向集中、一个测全球公民间的横向重排——大象曲线是r>g在全球尺度的投影：资本回报不只压过工资，还重画了国家间的赢家地图。",ev:"emp",s:3},
{f:"milanovic",t:"casedeaton",type:"coupling",label:"停滞的注脚",m:"大象曲线鼻根部的凹陷——全球第80分位上下的发达国家中下层增长近零——正是凯斯-迪顿「绝望死亡」人群的收入侧写：同一批人在分配曲线上停滞三十年，在死亡率曲线上开始反向上升。米兰诺维奇给宏观分配坐标，凯斯-迪顿给死亡率的兑现——全球化的输家不是全球穷人而是富国工人，这个命题在两个数据集上互相签名。英国脱欧与民粹反弹都被这条边翻译成分配语言。",ev:"emp",s:3},
{f:"milanovic",t:"human_capital",type:"tension",label:"国籍>技能",m:"人力资本模型说收入差距的主因是技能存量；米兰诺维奇的「国籍租」直接拆台：出生国别可解释全球收入差距六成以上——投胎在哪比技能更能预言收入。同一个人跨过边界收入立刻重估，说明价格付给位置不付给人。技能决定论在全球数据面前量级不足：禀赋回报的前提是边界先分配了机会集——位置先于技能。「国籍租」概念给位置优先性一个可估的系数。",ev:"emp",s:2},
/* ══ 社会学 soc ══ */
{f:"tonnies",t:"durkheim_division",type:"genealogy",label:"二分改写",m:"滕尼斯1887年劈出共同体与社会：本质意志的有机归属 vs 选择意志的人工结合——现代化=共同体被置换的凉薄进程。涂尔干的机械/有机团结把这个怀念性二分改写成功能分析：共同体不是失去的天堂，而是整合的一种技术形态——分工创造的互赖本身就是团结来源。二分的语法是滕尼斯给的、去浪漫主义化是涂尔干做的。机械/有机团结的二分语法源头就在这条谱系上。",ev:"fw",s:3},
{f:"tonnies",t:"putnam",type:"coupling",label:"共同体衰亡",m:"滕尼斯的共同体消亡叙事是定性的：选择意志置换本质意志、归属换自由。帕特南的独自打保龄给它接上量化续写：教会、会所、保龄球馆的衰退曲线把「共同体在退场」变成可测存量——社会资本即共同体在数据里的名字。一个给理想型、一个给时间序列——「凉薄化」第一次有了趋势线。Putnam的队列分解证明衰落主要是人换不是人变——共同体消亡的计量版。",ev:"fw",s:2},
{f:"tonnies",t:"soc_ties",type:"coupling",label:"归属=生理",m:"滕尼斯说共同体的本质意志是人「天然属于彼此」；社会整合-死亡率的流行病学给这个归属一个硬读数：社会纽带密度前瞻预测死亡率——归属不是精神奢侈品而是生理防护层。共同体的收益可以在生存曲线上计价：「天然归属感」被剥夺时付的代价以年计——社会学二分在死亡率上找到了它的生物学注脚。Berkman与House的综述队列是这条边的流行病学底座。",ev:"emp",s:2},
{f:"tonnies",t:"bergerluckmann",type:"coupling",label:"归属=nomos",m:"滕尼斯说共同体成员在共享习俗中「天然属于彼此」——天然感是共同体的心理签名。伯格与卢克曼的建构论给了这个天然感一个机制：被社会建构的nomos被体验为自然秩序——归属感是建构物被忘掉了它的出生证。一个说「共同体让人觉得自然」、一个说「自然感是被造出来的」——礼俗社会的温暖本质是成功的客观化。「本质意志」其实是nomos被第一人称体验时的样子。",ev:"fw",s:2},
{f:"parsons",t:"davismoore",type:"genealogy",label:"AGIL→分层",m:"帕森斯的AGIL说社会系统靠四功能项维持；戴维斯-穆尔的功能主义分层正是这个体系在分层问题上的直接应用：位置按功能重要性排序、报酬按排序配给——分层成了「模式维持+适应」的均衡解。师徒谱系明确：帕森斯给功能必要性的方法论、学生把它推到最被争议的极端——不平等被解释成系统的需要而非权力的产物。Davis是Parsons的学生，1945年短文是AGIL的分层应用。",ev:"fw",s:3},
{f:"marx_class",t:"parsons",type:"tension",label:"需求vs支配",m:"帕森斯的AGIL把社会秩序写成四功能的均衡：位置与报酬是系统需要的配给。冲突派指控这是把支配写成需求：AGIL从不回答「谁的功能、对谁适应」——分层被说成必需，恰因问错了问题。功能主义与冲突论是二十世纪社会学最长的对台：同一份不平等光谱，一个读成系统的正常运转、一个读成支配的自我再生产。1968年后冲突论反攻使其退潮，但概念已渗入一切后续理论。",ev:"fw",s:3},
{f:"parsons",t:"kohli_mayer",type:"coupling",label:"维持的时间面",m:"帕森斯的角色互补把人格与系统咬合：我期待你演、你期待我演，制度化即期望的稳定互锁。科利的生命历程制度化是同一逻辑的时间面：教育-工作-退休的三段式人生正是模式维持功能在个体时间轴上的展开——生涯阶段是被制度化的角色序列。系统需要的不是抽象秩序而是被写好的人生表——角色互补排到时间上就成了三段式。Kohli明确把三段式人生当作帕森斯式制度化的个案。",ev:"fw",s:2},
{f:"luhmann",t:"marx_class",type:"tension",label:"蒸发支配",m:"卢曼的功能分化论说现代社会的首要结构不是阶层而是代码：经济支付/不支付、法律合法/非法、科学真/不真——各子系统自运转、无总指挥。冲突派指控这把「谁支配」蒸发成系统语法：不平等没有被解释而是被分配——教育码的真/不真、经济码的支付/不支付各自关卡叠起来就是阶层的去中心化版本，只是不再叫它阶级。阶层仍在，只是被切成各子系统准入门槛的叠加形态。",ev:"fw",s:2},
{f:"luhmann",t:"foucault_gov",type:"coupling",label:"系统自描述",m:"卢曼说子系统以二元代码自我描述：治理话语是系统的自我生产而非外部指令。福柯的治理术是同一现象的权力读法：自我企业家、被治理的灵魂正是系统自我描述在主体层的打印件——系统说「优化自己」，人就把这句话内化成使命。一个给系统的语法、一个给语法在人身上的执行——自创生的代码落地处叫自我治理。「人只是环境」的激进设定把治理对象换成了沟通回路。",ev:"fw",s:2},
{f:"luhmann",t:"swidler",type:"coupling",label:"代码剧目",m:"卢曼说各子系统供应二元代码：每个场域有自己的真值表；Swidler的文化工具箱说行动者从文化库存装配行动剧目——子系统的代码正是库存的供应端。系统论给「代码从哪来」（功能分化的产出）、工具箱理论给「人怎么用」（按情境组装）——宏观的代码分化与微观的剧目装配是一条供应链的两端。工具箱理论补上了卢曼不处理的行动端装配过程。",ev:"fw",s:2},
{f:"elias",t:"bourdieu",type:"genealogy",label:"宫廷→惯习",m:"埃利亚斯的宫廷社会早半世纪写出惯习的原型：凡尔赛礼仪是权力技术——谁能自如执行复杂仪式谁就保位，失仪即失势，外部强制沉淀为第二自然。布迪厄自认惯习概念深承埃利亚斯：宫廷礼节竞争就是场域与惯习的历史原型——身体的规训先于场域理论半世纪。一个是宫廷史的过程社会学、一个是场域的一般理论——谱系清晰到当事人自认。",ev:"fw",s:3},
{f:"elias",t:"khan",type:"coupling",label:"从容旧谱",m:"埃利亚斯的宫廷贵族用礼节精确排位：仪式执行度=位置安全度。可汗的特权民族志是同一技术在当代的变异：精英寄宿学校教的不是排他品味而是「从容」——在一切文化层间自如穿梭的身体技术。宫廷的失仪即失势=圣保罗的失态即出局：自我克制的身体化是阶级位置最古老的保值装置，三百年间只换了校服。《宫廷社会》里失仪即失势的逻辑在圣保罗校园里仍在运转。",ev:"fw",s:2},
{f:"elias",t:"goffman",type:"coupling",label:"礼仪→前台",m:"埃利亚斯记宫廷礼仪：每步每姿都是排位竞争。戈夫曼的拟剧论把同一技术民主化：人人有前台——印象管理不再是贵族专利而是日常互动的标配工艺。宫廷史给「自我表演」一个长时段祖源：现代前台是宫廷技术的普及化，只是赌注从封邑变成脸面——文明进程的礼仪沉淀在戈夫曼手里变成微观互动的语法。礼仪手册史证明文明是过程的副产品，前台是其普及版。",ev:"fw",s:2},
{f:"elias",t:"davismoore",type:"tension",label:"过程vs功能",m:"埃利亚斯的文明进程是「过程性」的反功能论：文明没有设计者、只有无计划的合力方向——把礼仪说成「功能需要」恰是事后归因的错觉。功能主义分层把不平等说成系统的需求配给；过程论拒绝功能归因——排位竞争是历史合力的产物，不为「服务」什么。一个是设计论的功能解释、一个是无设计师的过程解释——「为什么有分层」的两种根本答法。",ev:"fw",s:2},
{f:"giddens",t:"elder",type:"coupling",label:"使能本体论",m:"埃尔德生命历程五原则里的能动性原则——「人建构自己的生命历程」——需要本体论地基；吉登斯的结构二重性正好供给：结构既是行动媒介又是行动结果、同时是约束与使能——人用行动重写规则，轨迹因此不是滑轨而是续写。结构化理论是哲学版的能动性，生命历程范式是它的经验化人生研究——一个说「结构可被改写」、一个说「人生确在改写」。",ev:"fw",s:3},
{f:"bourdieu",t:"giddens",type:"tension",label:"内化vs二重",m:"布迪厄说结构被内化为惯习——社会写进身体成为生成机制；吉登斯说结构二重性——结构不外在于人而是行动媒介兼结果，「内化」因此是个错误的隐喻：结构不在你里也不在你外，而在实践的反复进行中。结构如何「在」的两种本体论：一个把结构埋进身体、一个把它挂在实践里——能动性余裕之争的形上学版本。Archer对二重性的批评——批判时刻与例行被混同——是争端的续篇。",ev:"fw",s:3},
{f:"giddens",t:"merton_strain",type:"tension",label:"结构外挂",m:"默顿的结构紧张仍把结构当外在压力物：文化目标与制度手段的错位挤压出失范——结构是从外面压人的东西。吉登斯要拆的正是这种残余：结构不是压力物而是行动的条件与产物——它不只挤压你还使你能。默顿式结构分析与吉登斯的二重性是结构概念的两代用法：一个把结构当重力、一个把它当语法。二重性要拆的正是「结构=外部压力」这个残余设定。",ev:"fw",s:2},
{f:"beck_risk",t:"kohli_mayer",type:"coupling",label:"三段式退场",m:"科利的生命历程制度化把人生写成教育-工作-退休的三段硬编码；贝克的个体化正是三段式的退场诊断：阶级、家庭、职业这些旧制度形态撤退，人被抛成自己人生的CEO——「制度化个体主义」是退场完成后的悖论形态：制度撤了但要求你更制度化地管理自己。一个给硬编码的结构、一个给结构退场后的生存形态——「解放」即风险的个人化。",ev:"fw",s:3},
{f:"beck_risk",t:"bauman",type:"coupling",label:"孪生诊断",m:"贝克的风险社会与鲍曼的流动现代性是同一诊断的德英双联：都说固态制度（阶级、终身雇、福利）熔解为个体必须自己承担的流体——风险按阶级落回地面 vs 有缺陷的消费者被排除。贝克给风险分配的政治经济学、鲍曼给液态存在的现象学——「自由」在两人笔下都是被迫的：你必须自己选择，因为没有结构替你选了。两人互引且同代——诊断的相似性是共享的时代经验而非巧合。",ev:"fw",s:3},
{f:"furstenberg",t:"beck_risk",type:"genealogy",label:"撤退=个体化",m:"贝克的个体化是欧洲诊断：制度化人生退场、自我成为工程。弗斯滕伯格的制度撤退是它的美国实证版：去工业化+文凭通胀+国家与雇主撤退，把成人转变的成本私有化给家庭——「延迟成人」不是不想长大而是制度真的撤了。一个给「制度化个体主义」的宏大命题、一个给它在中西部城市青年身上的兑现时间表。美国队列数据给这个欧洲命题补了兑现的时间表。",ev:"emp",s:2},
{f:"durkheim_division",t:"collins_irc",type:"genealogy",label:"仪式世俗化",m:"涂尔干的宗教社会学说仪式产出集体欢腾与社会团结；柯林斯把它世俗化成通用微观引擎：任何面对面际遇——会议、饭局、面试——都是互动仪式，产出情感能量与成员符号。从祭坛到会议室，机制没变：身体共在+共同焦点+情感连带=团结的再生产——宗教仪式是特例，互动仪式才是常态。柯林斯明言其模型是涂尔干仪式机制的世俗化推进。",ev:"fw",s:2},
{f:"goffman",t:"collins_irc",type:"genealogy",label:"互动+情感",m:"柯林斯明言互动仪式链是戈夫曼互动秩序的情感化推进：戈夫曼写前台技术与面子功夫——互动的形式；柯林斯给形式注入能量学——际遇给EE账户充放电，人趋向高回报际遇、躲避放电际遇，人格与圈层忠诚都是这条链的沉淀。拟剧论给互动的剧本、仪式链给剧本的燃料账——面对面的际遇第一次有了能量经济学。EE账户的充放电是这条边上最直觉的机制画面。",ev:"fw",s:3},
{f:"collins_irc",t:"sennettcobb",type:"coupling",label:"羞耻记账",m:"柯林斯的仪式链说失败际遇产出疏离与羞耻——EE账户被扣款；塞内特与科布的阶级隐痛正是这种扣款的累积账本：工人在机构遭遇中的微小羞辱——被怠慢、被说教、被简化——被记成尊严的慢性亏空。隐性伤害不是一次大伤而是千次小额放电——仪式链给记账的物理过程、隐痛给账本的阶级面。隐性伤害=千次小额放电的累积，这条耦合给它配上力学。",ev:"fw",s:2},
{f:"collins_irc",t:"lamont",type:"coupling",label:"符号=边界",m:"柯林斯说仪式产出群体符号：行话、徽章、默契是成员身份的硬通货；拉蒙的道德-文化边界研究的正是这些符号如何被用来划界——「我们这种人不那样活」的边界是被仪式产物执行的。一个是成员符号的生成机制、一个是符号的排除性使用——仪式链解释边界从哪来、边界理论解释符号用来干什么。成员符号的流通半径就是道德边界的可达半径。",ev:"fw",s:2},
{f:"blau_exchange",t:"blauduncan",type:"coupling",label:"同布劳两书",m:"布劳1964年的交换论问微观：恩惠欠到还不起就兑换成权力——宏观结构从交换失衡中涌现；他与邓肯1967年的地位获得模型问宏观：父职→教育→初职的路径系数怎么分解。两本书是同一作者的表里：一本给不平等的起始机制（交换不对称）、一本给不平等的传递图谱（路径分解）——微观涌现与宏观流动在一个人手里合拢。OCG模型是社会学量化传统的奠基数据工程。",ev:"fw",s:2},
{f:"blau_exchange",t:"coleman",type:"coupling",label:"恩惠存量",m:"布劳说恩惠欠到还不起变成权力；科尔曼的社会资本说「义务与期望」构成的信用额度正是恩惠债务的存量形式——可调用、可转移、按网络密度增值。交换论的债务在科尔曼手里升格为资本：义务是货币、期望是债权、网络是清算所——从一次恩惠到可继承的社会资本，是同一条债务经济学的资产化版本。科尔曼的「义务与期望」正是布劳恩惠债务的存量化表达。",ev:"fw",s:2},
{f:"blau_exchange",t:"goffman",type:"tension",label:"交易vs尊严",m:"布劳把互动读成成本-收益：恩惠、债务、权力都是交换账。戈夫曼派说互动有礼仪式尊严不全是交易——面子、体面、相互的仪式义务不能放进账簿，否则解释不了为何人宁可亏本也要保脸。交换论把人压扁成计算器，拟剧论还人一张脸——「互动的单位是利益还是脸」是微观社会学的老分歧。面子与体面是账簿记不进去的通货，却是互动真实结算的硬货币。",ev:"fw",s:2},
{f:"weber_iron",t:"dimaggio_powell",type:"genealogy",label:"铁笼上锁",m:"韦伯的铁笼是理性化的宿命：科层效率把人关进理性计算的结构。迪马久与鲍威尔1983年重访铁笼并换引擎：理性化不再来自效率竞争而来自合法性压力——强制、模仿、规范三机制让组织「长得像大家」本身就是入场券。铁笼第二次上锁：第一波是效率焊的门、第二波是合法性焊的门——理性化的引擎换了，笼子更牢。标题The Iron Cage Revisited即明说是铁笼的重访。",ev:"fw",s:3},
{f:"dimaggio_powell",t:"collins",type:"coupling",label:"规范=文凭机",m:"规范性同构说专业教育与职业共同体输出统一模板——文凭制度正是这个机制的核心载体：柯林斯的文凭社会讲地位群体用文凭设封闭边界，DiMaggio-Powell补上组织面：专业化是规范同构的供应商，文凭通胀是同构压力在简历层面的通胀。一个是地位竞争的文化逻辑、一个是组织同构的制度机器——文凭热在两条边上共振。",ev:"fw",s:2},
{f:"dimaggio_powell",t:"emi",type:"coupling",label:"同构=换维维持",m:"有效维持不平等说：当入学数量普及，优势阶级退守质量维——不平等换维维持。制度同构是组织层的同款引擎：强制、模仿、规范三机制让门槛永远在移动——你有文凭我加认证、你有经验我要匹配度。EMI在人口层讲换维、同构在组织层讲换维——维持不平等的不是守门人而是门槛本身的漂移。同构三机制是组织层「换维维持」的执行引擎之一。",ev:"fw",s:2},
{f:"dimaggio_powell",t:"rivera",type:"coupling",label:"匹配=筛选端",m:"规范性同构的入口筛选是什么？里维拉的精英招聘给出答案：「文化匹配」——谈吐、话题、从容——是规范模板的面试形态：雇主找的是「像大家的人」，同构压力在招聘端变成fit筛选。制度同构给「为什么组织要同质化」的机制、招聘民族志给同质化的执行现场——制度压力的具体执行者是面试官。Rivera的EPS招聘样本是规范同构最顶端的入口现场。",ev:"emp",s:2},
{f:"parkin_closure",t:"abbott",type:"genealogy",label:"管辖权=封闭",m:"帕金的社会封闭说支配靠排斥与篡夺双机制；阿伯特的管辖权把这个机制职业化：职业系统就是管辖权的战场——谁能把某类问题定义为排他领地（医生抢「治疗」、会计师抢「审计」）谁就拿到执照护城河。管辖权=排斥机制在职业场域的系统化：封闭的一般理论在职业系统里变成可观察的攻防战。管辖权竞争靠抽象知识作货币——封闭的技术形态。",ev:"fw",s:3},
{f:"abbott",t:"collins",type:"coupling",label:"管辖通膨",m:"阿伯特说管辖权竞争的货币是抽象知识——越抽象越能守领地；柯林斯的文凭通胀是同一竞争在凭证维的膨胀：门槛被竞争抬高，文凭从技能证变成入场券——管辖权攻防的通膨面。一个是职业间抢地盘的战争、一个是地盘门票的价格飞涨——管辖权的军备竞赛就是文凭通胀的上游。执照护城河越挖越深，门票价格随之飞涨——两个「通胀」在同一场战争里互为表里。",ev:"fw",s:2},
{f:"sorokin",t:"blauduncan",type:"genealogy",label:"通道→路径",m:"索罗金1927年盘点社会流动通道：军队、教会、学校、婚姻像泵站一样抽人升降——这是领域的命名书。Blau与Duncan四十年后把通道清单翻成路径系数：父职→教育→初职的分解模型把「哪条通道抽多少人」变成可估的统计结构。通道学的类目被翻成路径分析的参数——流动研究从清单时代进入测量时代。从1927年命名书到1967年OCG模型，流动研究从类目进入系数。",ev:"fw",s:3},
{f:"sorokin",t:"turner_mobility",type:"genealogy",label:"通道两型",m:"索罗金的通道清单是未分型的枚举：军队、教会、学校、婚姻都在抽人。特纳的赞助/竞争流动给清单加上制度精修：通道分二型——赞助制下精英提前挑人（英国文法学校）、竞争制下人人赛跑到终点（美国高中）——同样的泵站有不同的阀门逻辑。通道清单变成通道类型学。英国文法学校与美国高中是两种阀门逻辑的标本——清单变成类型学的关键一步。",ev:"fw",s:2},
{f:"sorokin",t:"lubrano",type:"coupling",label:"流动代价",m:"索罗金1927年就记下流动的心理代价：上升者的失调与断裂感——他在前统计时代只能记一笔。卢布拉诺的跨阶层者民族志是这笔账的当代详录：straddler在两个世界间的不合群、口音焦虑、家庭疏远——流动代价从一句话长成整本民族志。最早提出命题的人与最晚提供证据的人，在这条边上隔八十年握手。跨阶层的失调与断裂感在民族志里长出完整的形状。",ev:"fw",s:2},
{f:"blauduncan",t:"wisconsin",type:"genealogy",label:"链条加温",m:"Blau与Duncan的地位获得模型是冷链条：父职→教育→初职的路径系数全是位置变量。威斯康星学派给它加温：在硬路径里插入社会心理中介——重要他者的鼓励→期望→投入，家庭背景的效应大半经心理链传导。OCG框架的社会心理化续章：结构不是直接压在人身上，是被翻译成志向再起作用——「位置经由心灵」。1969年ASR那篇用威斯康星男生长追数据做了证明。",ev:"emp",s:3},
{f:"wisconsin",t:"macleod",type:"coupling",label:"期望链底层",m:"威斯康星模型测期望链：重要他者鼓励→高期望→更多投入。麦克劳德的志向持平是这个链条的底层民族志版：Hallway Hangers的期望被现实可能集调平——「重要他者」在公屋里不供应高期望，链条在起跑前就断了。路径模型的中介变量在民族志里显出它的阶级配给：期望不是私人心理而是被供应的。两组青年的对照是期望链在不同供给端的运行实录。",ev:"fw",s:2},
{f:"wisconsin",t:"bourdieu",type:"tension",label:"中介vs生成器",m:"威斯康星模型把期望当可拆分的中介变量：背景→期望→投入→结果，链条可在问卷里逐环测量。布迪厄的惯习是一体化生成器：知觉、期望、行动原则同时被位置铸成——「期望」不是独立中介而是惯习的一个读数。量化路径分析与惯习理论在「期望是什么」上的方法论分界：变量可分离 vs 生成器不可拆。这条张力也是量化与民族志两条方法论传统的分界。",ev:"fw",s:2},
{f:"mannheim",t:"riley",type:"genealogy",label:"位置→队列",m:"曼海姆的世代位置是概念：一代人=被同一历史时段相似经验定位的人群。赖利的年龄分层把它操作化：队列流（cohort flow）成为可追踪的人口结构——世代位置变成队列分析的自变量。从「代的问题」的哲学设问到队列研究的方法标配：世代位置在人口学里找到了它的测量身体。队列流概念使「代」从哲学设问变成人口结构变量。",ev:"fw",s:2},
{f:"mannheim",t:"elder",type:"coupling",label:"位置×年龄",m:"曼海姆说历史事件打在哪个世代身上是位置问题：同代人共享关键期烙印。埃尔德的历史时空原则把这个判断个体化：大萧条打中谁取决于当时几岁——历史时机×生命阶段的乘积决定经验形态。一个给世代结构、一个给结构里的个人轨迹——「历史在谁身上留下印」需要世代位置与生命阶段两个坐标定位。Elder的《大萧条的孩子》是这条耦合的实证纪念碑。",ev:"fw",s:3},
{f:"mannheim",t:"cad",type:"coupling",label:"代内发散",m:"曼海姆的世代单元说同一事件对不同群体印记不同——代内已经分层。累积优势正是代内发散的机制：同一世代位置内部的初始小差异被富者愈富放大成代内大分层。一个说「同代不同单元」、一个说「同单元还在发散」——世代位置内部的再分层是两条文献的共同对象。「同代不同命」在此被机制化——世代单元内部的再分层即CAD的队列版对象。",ev:"fw",s:2},
{f:"elder",t:"clausen",type:"operationalizes",label:"能动性可测",m:"埃尔德的能动性原则说人建构自己的生命历程——原则但不可测；克劳森把伯克利队列追到六十岁给出测量版：计划性能力（自知+现实目标+坚持）是五十年最强预测器，青少年期具备者职业婚姻全面更稳。能动性不是宣言而是一种累积资产——可测、可追踪、有阶级分布——生命历程的能动性原则第一次有了心理测量学底盘。六十年重访使「建构工具何时被分配」变成可估问题。",ev:"emp",s:3},
{f:"clausen",t:"cad",type:"coupling",label:"心理引擎",m:"累积优势是结构机制：小差异经正反馈放大。克劳森的计划性能力给它配了心理级引擎：具备者选更好的教育、配偶、工作——每次选择都是CAD放大的一个齿轮。一个是差距为何变大的结构面、一个是放大如何被个体执行的能力面——CAD在个体层的涡轮机就是计划性能力。自知→选择→资源→整合度这条传导路径正是CAD的微观链。",ev:"fw",s:2},
{f:"clausen",t:"kegan",type:"coupling",label:"自知×自我导向",m:"克劳森的计划性能力三成分之首是自知：知道自己能做什么。Kegan的主体-客体五阶是自知的发展深度版本：自我导向能力随阶位增长——第4阶的自我 authored 正是计划性能力需要的结构。一个是生命历程队列里的预测因子、一个是发展序列里的结构指标——「知道自己」在两套文献里都是核心资产。两套文献都把「知道自己」当核心资产——一个测预测力、一个测阶位。",ev:"fw",s:2},
{f:"clausen",t:"bourdieu",type:"tension",label:"能力=惯习?",m:"克劳森的计划性能力是统计上成立的预测器；布迪厄派会立刻质疑：这能力就是惯习换名——「自知+现实目标+坚持」正是中产位置的知觉产出，测它等于测惯习却不承认。能动性可测 vs 能动性即位置：计划性能力的阶级分布本身支持布迪厄——但克劳森的贡献是让「惯习的效果」第一次变成可估的系数。测惯习的效果而不承认惯习，是量化传统的典型姿态。",ev:"fw",s:2},
{f:"furstenberg",t:"mortimer",type:"coupling",label:"缓冲微机制",m:"弗斯滕伯格的制度撤退说成年转变成本被私有化给家庭——能供孩子慢慢到位的家庭赢。莫蒂默的YDS数据给出缓冲期的微观内容：低强度有指导的青少年工作是过渡资产——守时、责任感、职业探索、成人社会网——正是「缓冲期里该装什么」的清单。制度撤退给结构、青少年工作给结构里的填充物——过渡是被设计还是被消耗，是个阶级问题。",ev:"emp",s:2},
{f:"elder",t:"mortimer",type:"operationalizes",label:"时机实证",m:"埃尔德的时机原则说同一经验在不同年龄兑现不同；莫蒂默的YDS纵贯给了直接实证：同一份打工，15岁低强度是训练（发展资产）、25岁高强度是死胡同（过渡陷阱）——「什么时候遇到」比「遇到什么」更要命。时机原则从抽象原则变成被测的效果修饰：年龄不是背景变量而是效应本身的一部分。YDS千人纵贯1988-2000是这条操作化的数据底座。",ev:"emp",s:2},
{f:"mortimer",t:"turner_mobility",type:"coupling",label:"隐性赞助",m:"特纳的赞助/竞争流动说通道分两型：有人被提前挑中、有人赛到最后。莫蒂默的低强度指导性工作是隐性赞助通道的实证形态：有指导的工读不是随便打工——是有人带你认识成人世界、被放进「将来有人托底」的轨道。青少年工作的好坏不是工时问题而是它连着哪种流动通道——赞助制在日常工读里悄悄运转。YDS数据显示这类工读成人的教育收入双收。",ev:"fw",s:2},
{f:"kohli_mayer",t:"esping",type:"genealogy",label:"三段式母体",m:"科利的生命历程制度化把人生写成教育-工作-退休三段式；埃斯平-安德森的福利三世界回答这三段式的体制母体是谁：自由体制市场化、保守体制职业保险化、社民体制全民化——同一个25岁在哥本哈根与底特律的结构位置根本不同。生涯制度的类型学：三段式人生在三种福利世界里是三种不同的人生。三世界的去商品化差异就是三段式人生的三种硬编码版本。",ev:"fw",s:3},
{f:"esping",t:"billari",type:"coupling",label:"体制→转轨",m:"Billari的成年转变研究记下南欧「latest-late」模式：最晚离家、最晚婚育。埃斯平的类型学给它体制解释：保守-家庭主义体制靠家庭承接风险——转轨成本被家庭吸收所以转轨最晚。一个给跨国时间表、一个给时间表背后的体制代码：成年转变的快慢是福利体制的输出变量。南欧的家庭主义把转轨风险内部化——转轨最晚是体制的输出读数。",ev:"emp",s:2},
{f:"esping",t:"furstenberg",type:"coupling",label:"自由体制极端",m:"埃斯平的三世界里美国是自由体制的极端：市场+残补救助、去商品化最低。弗斯滕伯格的制度撤退是这个体制在成年转变上的兑现：国家与雇主撤退、转变成本私有化给家庭——「能啃老多久」成为隐形分层。类型学给体制名、撤退史给体制的生涯面：美国的延迟成人是自由体制福利安排的直接产品。自由体制的极端化把转变成本几乎全部私有化给家庭。",ev:"fw",s:2},
{f:"esping",t:"standing",type:"coupling",label:"不稳者分布",m:"埃斯平说去商品化决定人多大程度能不卖劳动力而活；斯坦丁的precariat是去商品化最低的体制里最厚的人群：自由体制里不稳定无产者最庞大，因为风险无人能替你扛。福利类型学预测这层人口的跨国分布——不稳定化的深度不是技术给的而是体制给的：同样全球化，三世界产出三种厚度的不稳定。去商品化越低这层人口越厚——体制给不稳定化定深度。",ev:"fw",s:2},
/* ══ 精神分析/临床 psy ══ */
{f:"freud_dreams",t:"freud_defense",type:"genealogy",label:"梦=实验室",m:"梦工作是压抑理论的实验室：被压抑的内容经凝缩、移置、象征、润饰改装后返回显梦——压抑装置如何变形内容，在梦里看得最清。《释梦》第七章顺手建起第一地形学，「压抑与防御」的整套机制在这里先被试运行：伪装不是症状专利而是潜意识出口的通用工艺——梦是防御机制最诚实的展示窗。梦因此成了防御机制最便宜的观察窗口。",ev:"fw",s:2},
{f:"freud_dreams",t:"hysteria",type:"genealogy",label:"同出一炉",m:"癔症研究与释梦是同一条生产线的前后段：布洛伊尔-弗洛伊德的宣泄法发现症状是被压抑内容的妥协形成物；《释梦》把同一机制推广到每个睡眠者——梦与症状同为压抑物的改装返回。癔症给「内容要出来」的临床证据、释梦给「怎么出来」的工艺图——转换与梦工作是同一种妥协形成技术的两个名字。宣泄法的临床经验被推广为整夜上演的普遍工艺。",ev:"fw",s:2},
{f:"freud_psychosexual",t:"erikson",type:"genealogy",label:"时刻表换代",m:"弗洛伊德的性心理阶段是快感带的时刻表：口-肛-性器-潜伏-生殖，固着与退行留下性格遗迹。艾瑞克森的八阶段把时刻表从快感带换成社会危机：信任对不信任、自主对羞怯、主动对罪疚——同一序列结构，驱动从力比多投注改写成心理社会任务。躯体的阶段变成了关系的阶段——八阶段是性心理序列的社会化重写。快感带时刻表换成社会危机时刻表——结构保留、驱动换芯。",ev:"fw",s:3},
{f:"freud_psychosexual",t:"freud_superego",type:"produces",label:"俄狄浦斯落幕",m:"性心理序列的枢纽是性器期的俄狄浦斯情结：对同性父母的认同解决了爱憎两难——情结落幕时内化的产物就是超我：父母的禁令、理想与惩罚被搬进内心常驻。阶段表给「什么时候」、超我给「留下什么」——俄狄浦斯不是过路的剧而是永久的拆迁：它拆掉时留下的建筑叫良心。《自我与本我》1923年给这个拆迁产物正式命名为超我。",ev:"fw",s:3},
{f:"freud_psychosexual",t:"bowlby",type:"tension",label:"驱力vs照护",m:"性心理阶段把发展写成驱力投注史：口唇期是力比多挂在嘴上。鲍尔比把同一时段改写为照护质量史：发展差异不是力比多在哪、而是依恋对象如何回应——早期不良不是固着而是不安全依恋模式的写入。驱力阶段论与依恋理论在「最初几年发生了什么」上各执一词：一个要本能的账、一个要关系的账——谁记账决定了「病从哪来」的答案。",ev:"fw",s:3},
{f:"freud_civilization",t:"freud_superego",type:"coupling",label:"罪疚=税金",m:"文明及其不满的机制核心：攻击性不外泄就内转，被超我收编为罪疚——「文明的代价是幸福感的丧失，由罪疚的增高来偿付」。超我在此放大为文明论装置：它不是个人良心的私设法院，而是文明收取本能税的税务局——规范内化的大叙事版，每个合格公民都背着一份缴不完的罪疚。个体病理与文明病理在此共用同一个公式：罪疚预算随文明等级同步扩张。",ev:"fw",s:3},
{f:"freud_civilization",t:"fromm",type:"genealogy",label:"文明税社会学",m:"弗洛伊德的文明收本能税：规范内化、罪疚升高、幸福上缴。弗洛姆的社会性格把这个税则阶级化：不是抽象的「文明」收税，而是特定经济结构逼出特定性格——市场性格就是「我即你所欲」的商品化自我，把压抑写成营销规范。社会精神分析传统的接力：文明税从元心理定理变成阶级社会的诊断工具。费伦齐到弗洛姆的布达佩斯-法兰克福线承接的正是这个接口。",ev:"fw",s:2},
{f:"freud_civilization",t:"frankl",type:"tension",label:"压抑vs真空",m:"弗洛伊德1930年的答案：人不幸福因为文明收本能税——罪疚是进步的价签。弗兰克尔1946年的答案：人不幸福因为存在真空——不是税太重而是意义缺席。一个说幸福的障碍是过度压抑、一个说障碍是意义供给的中断——晚期现代恰好同时验证两者：本能税被功绩制自我剥削代收，意义供给被交给个人自负盈亏。「制度收本能税」的框架至今仍是批判理论的底盘。",ev:"fw",s:2},
{f:"freud_transference",t:"freud_repetition",type:"coupling",label:"重演代替回忆",m:"重复强迫说人被迫重演早年的创伤模式而非回忆它；移情正是重复强迫的诊室版：病人把早年对重要客体的欲望-情感整套搬到分析师身上——「你无法在缺席中杀死任何人」，旧戏只有在治疗室重演才能被修通。元心理学概念与临床技术在此互相定义：移情让重复强迫第一次有了可工作的操作间。以重演代替回忆——移情神经症替代了原发神经症的工作位。",ev:"fw",s:3},
{f:"freud_transference",t:"klein",type:"genealogy",label:"双人共谋",m:"弗洛伊德的移情是单向移植：病人把旧模板贴到分析师这块空白幕布上。克莱恩之后经投射性认同把它改写成双人共谋：病人不只投射，还实际诱发分析师产生特定情感——反移情从干扰升格为诊断通道，温尼科特与海曼1950年翻案完成。移情从「病人的重演」变成「两人共演的场」——关系精神分析的先声在此。投射性认同与反移情翻案把单向移植改成双人共谋。",ev:"fw",s:2},
{f:"freud_transference",t:"bowlby",type:"coupling",label:"模板重演",m:"移情的临床宣称：旧关系模板会在新关系里重演。鲍尔比的内部工作模型是它的实证对照：早期照护经验沉淀为对关系的预期结构，在成人依恋、育儿、治疗关系里可测地重演——AAI编码与陌生情境实验把「重演」从临床智慧变成可测机制。分析师的躺椅与依恋实验室拍到同一件事：模板不退休，只换对象。「关系模式自我重演」已是跨学派共识，差别只在测量仪器。",ev:"emp",s:3},
{f:"rank_birth",t:"klein",type:"genealogy",label:"前俄狄浦斯转向",m:"兰克1924年把焦虑原型从阉割改锚到出生：与母体的分离先于一切冲突。这个「分离先于驱力」的转向是前俄狄浦斯革命的早熟预告——克莱恩随后把理论重心整个移向母亲-婴儿位态：偏执-分裂位与抑郁位都是与母亲客体的早期关系质量。兰克用单一创伤开错了药，但他打的方向灯被整个客体关系时代继承：母亲是心理学的新中心。",ev:"fw",s:2},
{f:"rank_birth",t:"balint",type:"genealogy",label:"缺陷=分离",m:"兰克说出生是最初断裂：与母体合一被暴力终结，此后一切分离焦虑都是重演。巴林特的基本缺陷把同一线索临床化：早期母婴关系的断裂留下「缺陷区」——不是冲突（有东西在打架）而是欠损（有东西没给到）。从分离原型到基本缺陷，前俄狄浦斯线把病因从「冲突」改写为「缺席」——治疗从解释变成补缺口。巴林特本人在布达佩斯受的正是兰克圈子的熏陶。",ev:"fw",s:2},
{f:"rank_birth",t:"rollo_may",type:"genealogy",label:"意志传美",m:"兰克被逐出IPA后在美国另起炉灶；罗洛·梅吸收了他的意志与创造力概念——《爱与意志》里意志作为存在的组织能力、魔性作为被压抑的生命力，都是兰克线的美国移植。存在心理学接住的是兰克最反弗洛伊德的遗产：人不只是被驱力推着走，意志可以主动承担分离——出生创伤的相反面是自由地出生。限时治疗的主张也是兰克留给短程治疗的胚胎。",ev:"fw",s:2},
{f:"jung_archetype",t:"freud_defense",type:"tension",label:"仓库vs结构",m:"弗洛伊德的无意识是仓库：被压抑的个人内容堆在里面，内容决定了解读。荣格的无意识分两层：个人仓库之下还有物种共享的原型层——空洞形式而非内容，像器官一样被遗传。两种无意识本体论的分裂：一个说潜意识装的是被逐出的个人史，一个说底层写的是人类共同的预装格式——「潜意识是内容还是结构」是深层心理学的第一次分家。",ev:"fw",s:3},
{f:"jung_archetype",t:"lacan",type:"coupling",label:"先写的形式",m:"荣格的原型与拉康的大他者是远亲：共享「主体被先于自身的形式书写」的命题——人出生前结构已在。差别在材质：拉康的形式是能指结构（语言秩序），荣格的是生物沉淀（祖先经验的满溢）——一个是符号性的、一个是本能性的先验。两者都给「自我」降格：我不是自己的作者——只是被先写形式填满的后来者。一个说形式是生物沉淀、一个说形式是能指结构——先写性的两种材质。",ev:"fw",s:2},
{f:"jung_persona",t:"winnicott",type:"coupling",label:"面具=假我",m:"荣格的人格面具是对社会期待的适应装置，认同面具就空心化；温尼科特的假我是为顺从环境构筑的自体壳——同一现象的跨谱系对偶，只是病因叙事不同：荣格说补偿（阴影反扑），温尼科特说顺从（真我退缩）。两位都警告「标准好人」是被裁剪过的人——面具与假我是二十年代平行发明的同一警报：过度适应本身是病。病因叙事不同——补偿对顺从——警报内容相同。",ev:"fw",s:3},
{f:"foucault_disc",t:"jung_persona",type:"coupling",label:"面具车间",m:"荣格说面具是必要但危险的适应：认同它就空心化。福柯的规训给出面具的集体铸造车间：全景敞视让标准化自我呈现变成自动装置——面具不是个人选择而是制度量产。个体心理学与社会学在此对接：阴影的内容是私人的、面具的规格是公共的——「什么样的人算得体」这个模板，从来不是自己设计的。制度量产标准自我的车间在全景敞视里常年开工。",ev:"fw",s:2},
{f:"jung_persona",t:"fromm",type:"coupling",label:"我即你所欲",m:"弗洛姆的市场性格说现代人把自己当商品：人格即包装，「我即你所欲」——自我被市场期待塑形。这正是面具认同的经济学版：角色吞噬人格、市场价值取代自性。荣格警告认同面具=空心人；弗洛姆证明空心是结构性的——当自我变成待售商品，面具不再是对社会的适应而是对市场的求偶信。两人共享法兰克福-苏黎世的诊断：空心是结构性的。",ev:"fw",s:2},
{f:"jung_individuation",t:"loevinger",type:"coupling",label:"整合两轨",m:"荣格的个体化把后半生发展写成与无意识的对质史：拆面具、对质阴影、趋向自性整合。洛文杰的自我发展阶段把成年发展写成认知-道德结构的升级序列：从顺从到自主到整合——同一条「后半生长大」的命题，一个用神话语汇、一个用量表语汇。个体化的「成为完整的自己」与自我发展的「整合阶段」是同一顶点的两种测绘法。句子完成测验（SCT）把「整合」变成可评分的阶段。",ev:"fw",s:2},
{f:"jung_individuation",t:"mcadams",type:"genealogy",label:"整合操作化",m:"荣格说后半生任务是人格整合：对立两极在超越功能中生成新秩序。麦克亚当斯的叙事同一性是它的实证后裔：人格整合被操作化为生命故事的连贯建构——redemption与commitment序列是「超越功能」的可测版本，连贯故事=整合的临床表现。神话语汇换成编码手册，自性实现变成可打分的叙事结构——谱系直接到方法论。",ev:"fw",s:2},
{f:"jung_individuation",t:"frankl",type:"coupling",label:"后半生工程",m:"荣格与弗兰克尔共享「后半生=意义工程」的存在底色：个体化是向完整性的行进、意义意志是向意义的行进——两位都把中年的空虚读作成长的召唤而非衰退。个体化要拆面具面对阴影，意义意志要在苦难中取态——中年危机在两种框架里都是同一扇门的两种把手：往里推是自性、往外推是意义。对后半生的正面命名是二者共同的贡献。",ev:"fw",s:2},
{f:"adler_inferior",t:"horney",type:"coupling",label:"处境同盟",m:"阿德勒是最早把神经症从驱力改写到处境的人：真实自卑处境（弱小、缺陷、贫困）→补偿性建构人格。霍妮的基本焦虑是同一路线的文化版：神经症源于孩子在敌对世界里的不安全感——处境而非驱力致病。两位新弗洛伊德派同盟都拒绝「病在驱力」：一个在自卑补偿、一个在基本焦虑——神经症是处境的产物，人格是处境的适应工事。",ev:"fw",s:3},
{f:"adler_inferior",t:"kohn",type:"coupling",label:"处境→定向",m:"阿德勒说人格是对处境的补偿性建构：真实自卑处境塑造「追求优越」的具体形式。科恩的阶级与从众是它的量化远亲：职业条件塑造父母价值观、价值观塑造教养——处境如何塑造自我定向有了实证链。一个给「处境-补偿」的临床直觉、一个给「处境-价值」的统计证据——人格被位置写出的命题，在诊所与问卷里各得印证。Kohn与Schooler三十年追踪是这种互证的纵贯证据。",ev:"emp",s:2},
{f:"adler_inferior",t:"pcr",type:"coupling",label:"达标换爱",m:"阿德勒说神经症是错误补偿：用虚构的优越目标绕开真实任务。条件性积极关注给出制造错误补偿的机制之一：「被爱=达标」让孩子把价值感挂在表现上——补偿性追求由爱的条件性亲手铸造。罗杰斯-Deci线证明有条件关注换来脆弱自尊，阿德勒框架补上人格后果：追求优越常是被条件化的爱在驱动。被条件化的爱亲手铸造补偿性追求——这是达标换爱的成人版。",ev:"fw",s:2},
{f:"adler_birth",t:"lareau",type:"coupling",label:"家内×家间",m:"拉鲁的协作培养/自然成长看的是家庭间的阶级差异：中产与劳工两种教养逻辑。阿德勒的家庭星座看的是家庭内的位置差异：同一家庭不是同一环境——长子被废黜、次子追赶、幼子被溺爱，每个出生位置是一个不同的发展坐标系。两种分层互为补轴：家间差异是阶级分配的、家内位置是手足排序的——「家庭环境」从来不是单一变量。",ev:"fw",s:2},
{f:"adler_birth",t:"kohn",type:"coupling",label:"位置→知觉",m:"阿德勒说出生位置的效应不是命定而是「位置-知觉」：孩子对处境的解读（而非处境本身）塑形生活风格。科恩的链条有同样结构：职业条件→价值观→教养——客观位置经由主观价值中介。两人共享的方法论：人格研究的分析单位不是位置而是位置被知觉的方式——结构要穿过解释才到达人格。大样本证据对客观序位很残酷，存活形式是「主观位置感」。",ev:"fw",s:2},
{f:"maslow_needs",t:"sdt",type:"genealogy",label:"砍掉递进",m:"马斯洛给动机排座次：匮乏需要满足后成长需要登场——预付费模型。Deci与Ryan的自我决定论继承其成长动机内核但砍掉递进假设：自主、胜任、归属是并列的基本心理需要，任何时候缺失都致病——不需要先通关底层。人本主义纲领被认知实验化：层次换成了清单，「自我实现」被拆成可测的三营养素。金字塔不是他画的、严格逐层也不是他的主张——但递进假设被SDT正式拆除。",ev:"fw",s:3},
{f:"maslow_needs",t:"scarcity",type:"coupling",label:"带宽验证",m:"马斯洛的预付费结构预言：匮乏需要未满足时垄断意识——高层需要进不了场。稀缺认知税是这个预言的行为版实证：带宽被生存占用时，认知与自控的高层功能实质塌缩——穷人不是不想要自我实现，是认知额度被底层需要吃完了。层次学说争论了半世纪，带宽研究用认知税的机制给它补了一条硬证据腿。Mani等的蔗糖农夫实验显示收获前后认知差近一个IQ档。",ev:"emp",s:2},
{f:"maslow_needs",t:"ehrenberg",type:"tension",label:"权利→义务",m:"马斯洛把自我实现写成动机金字塔的顶端权利：匮乏解决后生长自然登场。埃伦伯格的成为自我的疲倦给出反转诊断：当「成为自己」从权利变义务——自我实现被功绩制律令化——顶端需要就变成了新的压迫源。同一概念的两种效价：作为匮乏解除后的生长 vs 作为永不打烊的自我优化任务——人本纲领被它要反抗的系统收编。自我实现从权利变义务，是人本纲领被功绩制收编的反转。",ev:"fw",s:2},
{f:"rogers_unconditional",t:"pcr",type:"produces",label:"实证镜像",m:"罗杰斯预言：价值条件扭曲实现倾向——「你乖我才爱你」让孩子内化条件、经验与自我概念错位。Assor与Deci的PCR研究是这个预言的实证版：条件性积极关注换来内摄调节与脆弱自尊——爱随表现给予/收回时，孩子学会的是条件性的自我。人本命题第一次有了实验与量表证据：黑暗镜像被测光，无条件关注的必要性被数据背书。",ev:"emp",s:3},
{f:"rogers_unconditional",t:"sdt",type:"genealogy",label:"自主继承",m:"罗杰斯的价值条件说扭曲发生于爱被条件化；SDT把这个洞察结构化为自主需要：内摄调节正是「把外部条件当自我价值」的动机形态——外在→内摄→认同→整合的内部化连续谱，就是价值条件从外部写入到自我收编的地图。人本主义的临床智慧被转码为动机科学：「成为真实的自己」变成「从外在调节移向整合调节」。衣钵由自主需要继承，但术语已换成可证伪的。",ev:"fw",s:3},
{f:"rogers_unconditional",t:"yalom",type:"coupling",label:"人本-存在同盟",m:"罗杰斯的人本与亚隆的存在治疗是同一阵营的分工：罗杰斯给关系技术——无条件关注、共情、真诚是改变的充要条件；亚隆给内容地图——死亡、自由、孤独、无意义是必须相遇的议题。一个说「怎么陪伴」、一个说「陪伴里会碰到什么」——人本-存在同盟里，治疗关系是药、终极关怀是病灶。罗杰斯1957年名文列的治疗充要六条是人本-存在同盟的技术宪章。",ev:"fw",s:2},
{f:"sullivan_interpersonal",t:"horney",type:"coupling",label:"文化学派",m:"沙利文、霍妮、弗洛姆同属美国文化学派/新弗洛伊德派：共享把神经症从驱力改写为人际-文化的纲领。沙利文的具体贡献是机制：焦虑经母婴共情联结人际传递、自我系统是为躲焦虑建的防盗网——人格=反复出现的人际情境模式。霍妮给文化病理的宏观画、沙利文给传染的微观管线——神经症的人际化在此获得工程学。美国文化学派的共享纲领：病在人际-文化而非驱力。",ev:"fw",s:3},
{f:"sullivan_interpersonal",t:"bowlby",type:"genealogy",label:"共情→依恋",m:"沙利文的共情联结说母亲焦虑不经学习直接感染婴儿——焦虑是人际传递的；鲍尔比的依恋理论把这个直觉安进行为系统框架：婴儿与照料者的情绪调节回路成为内部工作模型的原料。人际传递的临床直觉被依恋范式操作化——情感协调研究后来部分平反了共情联结：母亲-婴儿的情绪同步有实证踪迹。母亲焦虑感染婴儿的共情联结是依恋传导的前身。",ev:"fw",s:2},
{f:"sullivan_interpersonal",t:"aai_fonagy",type:"genealogy",label:"关系中成形",m:"沙利文的纲领「人格=反复出现的人际情境模式」与「自我系统在关系中成形」；Fonagy的心智化与AAI研究把这个纲领实证化：反思功能在依恋关系中发展——能读懂自己被读懂的能力，先在安全关系里被示范再被内化。「心智在关系中成形」从人际学派的信条变成可测的发展机制——AAI编码的就是这个成形的痕迹。Fonagy的反思功能概念给了「自我系统」一个操作化后裔。",ev:"emp",s:2},
{f:"mahler_separation",t:"bowlby",type:"coupling",label:"同田两仪",m:"马勒与鲍尔比看同一块母婴田地、用两套仪器：分离-个体化追踪内化的慢过程——共生、分化、练习、和解、客体恒常，「心理诞生」的时间表；依恋理论追踪行为系统的运转——安全基地、分离抗议、陌生情境。一个问「母亲如何被内化」、一个问「依恋如何被组织」——内化的时间表与行为的安全性是同一段双人舞的两种记谱法。Pine与Bergman的母婴观察记谱法与陌生情境互补。",ev:"fw",s:2},
{f:"mahler_separation",t:"klein",type:"tension",label:"时序竞争",m:"马勒的共生期在2-5月、和解危机在16-24月；克莱恩的偏执-分裂位与抑郁位放得更早——前几个月就运转。两套早期发展时序的竞争：心理诞生是慢过程（马勒）vs客体关系从第一天就在（克莱恩）——「正常自闭期」假设已被婴儿研究推翻，新生儿即对人有选择性，这使克莱恩一侧在时序之争中占了上风。客体关系起点被推得越早，分离-个体化越像晚到的故事。",ev:"fw",s:2},
{f:"mahler_separation",t:"balint",type:"coupling",label:"共生欠损",m:"马勒的和解危机说：学步儿意识到分离真相时的矛盾——既推开又黏住——若处理失败，边缘型与自恋病理的种子在此播下。巴林特的基本缺陷是同一逻辑的临床延伸：早期共生失败的欠损区——不是冲突没解决而是供给没到。「和解危机」生成机制与「基本缺陷」病灶形态，是分离-个体化线的正常端与病理端。Balint把失败定位在比马勒更早的「基本区」。",ev:"fw",s:2},
{f:"klein",t:"kernberg_bpo",type:"genealogy",label:"位态→层级",m:"克莱恩的偏执-分裂位与抑郁位原是婴儿发展的时序阶段；科恩伯格把它们改写成人格组织的结构层级：边缘人格组织=分裂主导的原始防御+保留的现实检验——介于神经症与精神病之间的第三层。位态从时间表变成了结构诊断学：不再问「你在哪个月」，而问「你的客体表征整合到哪层」——发展心理学被转译成诊断层级。组织层级判定依赖访谈者的理论眼光——这是其诊断学的软肋。",ev:"fw",s:3},
{f:"kernberg_bpo",t:"afreud_defense",type:"coupling",label:"防御分层",m:"安娜·弗洛伊德的防御机制编目把防御列成清单；科恩伯格把清单分层：原始防御组合（分裂居首，加投射性认同、原始理想化、全能、贬低）是边缘组织的标志，成熟防御属于神经症层——防御不再只是类型学而是结构深度的读数。编目给词汇表、层级给语法：防御机制「在哪个层运作」比「用哪一种」更有诊断力。分裂居首的原始防御组合是边缘层的标志签名。",ev:"fw",s:2},
{f:"kernberg_bpo",t:"kohut",type:"tension",label:"同病异读",m:"科恩伯格与科胡特为同一批自恋病人打了半辈子：科恩伯格看到整合失败——分裂的客体表征、攻击性压倒爱；科胡特看到供给断裂——selfobject供给不足、自体结构欠损。边缘组织的结构诊断与自体心理学的缺陷模型在病房里对同一症状给出相反处方：一个要在移情中整合分裂、一个要让自体客体经验被补供——精神分析内战的最著名战场。",ev:"fw",s:3},
{f:"mitchell_relational",t:"fairbairn",type:"genealogy",label:"收束客体",m:"费尔贝恩的道德防御说人宁可自认坏也不愿承认客体坏——关系需求先于一切。米切尔把这条线织进关系模型的立国宣言：人天生寻求关系本身而非驱力释放——费尔贝恩的客体寻求、温尼科特的假我、科胡特的自体客体被清点为同一范式的零件。关系精神分析是收束点：四条支流在「心灵本质上是人际的」这个公约数上汇合。格林伯格与米切尔的范式清点是立国前的清点工作。",ev:"fw",s:2},
{f:"mitchell_relational",t:"freud_transference",type:"genealogy",label:"幕布→双人场",m:"弗洛伊德的移情预设分析师是空白幕布：病人的旧模板投射上来、分析师只是支架。米切尔的关系模型把幕布撤了：分析情境是双人共同建构的场——分析师的人格、情感反应、理论选择都在共同编剧，「真实的相遇」取代中立匿名。移情从移植变成了协商：旧戏仍在重演，但对手演员开始改剧本。分析师的主观性被重新安置：不在场外而在场内共编。",ev:"fw",s:3},
{f:"mitchell_relational",t:"bowlby",type:"coupling",label:"关系第一性",m:"米切尔的关系模型与鲍尔比的依恋理论共享一个核心公理：人天生求关系不求释放——依恋是目的不是手段。但两条线的方法分家：关系学派走临床-诠释路（分析是双人建构），依恋走实证-发展路（行为系统可测）。关系第一性是公约数，方法论是分水岭——同一个假设在躺椅与陌生情境里长出不同的证据形态。AAI与移情焦点两种测量各自认领了这条公理的一半。",ev:"fw",s:2},
{f:"beck_triad",t:"freud_melancholia",type:"tension",label:"反驳内转",m:"弗洛伊德《哀悼与忧郁》说忧郁是愤怒内转：对客体的敌意被转向自我。贝克本想用病人证明它，数据却造反：抑郁者的自动思维不是压抑的敌意而是系统性负性偏差——认知三联征。忧郁病因学从内化客体换成认知图式：病不在「愤怒转向内」而在「我不可爱/无能」的图式在加工现实——愤怒让位给扭曲。1963年论文与1979年教科书把反驳做成了首个RCT背书的治疗学派。",ev:"emp",s:3},
{f:"beck_triad",t:"ehrenberg",type:"coupling",label:"疲倦邻域",m:"贝克的抑郁是认知扭曲：三联征由图式驱动。埃伦伯格的成为自我的疲倦是同一现象的社会学本体论：抑郁是自主规范过载——「成为自己」的律令人人可执行时，「不可能成为自己」成了新病理。一个把病灶放在图式里、一个把病灶放在规范里——认知治疗修加工、社会学要修律令——同一抑郁、两种归因层级。治疗的归因层级决定干预层级——修加工还是修律令。",ev:"fw",s:2},
{f:"beck_triad",t:"seligman",type:"coupling",label:"扭曲×归因",m:"贝克的认知三联征与塞利格曼的习得性无助-解释风格是同盟：无助不是事件的直接产物而是归因方式的产物——「是我的错、永远如此、事事如此」的内化归因就是负性图式的运转形态。认知治疗与归因再训练共享技术前提：如果忧郁是加工方式的病，改变加工就是治疗——两者都把「怎么想」当成了「怎么活」的杠杆。归因方式决定无助的形态——整合证据使认知路线成了循证治疗标准件。",ev:"emp",s:2},
/* ══ 批判理论 pol ══ */
{f:"arendt_vita",t:"marx_alien",type:"tension",label:"劳动不可神化",m:"阿伦特对马克思的核心异议：他把labor与work混为一谈、又把劳动神化为人的本质——在她看这正是病灶而非解药：把动物劳动者抬为最高范式，等于宣布消费循环是人生的完成态。异化四重规定要恢复劳动的尊严，三分法要恢复行动与工作的层级——两位都在批判现代性，但开出的药方相反：一个要劳动解放、一个要劳动降位。",ev:"fw",s:3},
{f:"arendt_vita",t:"bauman",type:"coupling",label:"世界性溶解",m:"阿伦特的「世界性」是耐久物的稳定性：桌、城、文本构成比人活得久的共同世界。鲍曼的流动现代性正是世界性的反面：固态世界熔解为液态流——无耐久物、无稳定结构，连「世界」本身都变成快消品。一个是工作（造持存）被劳动（消耗）吞没的诊断、一个是持存本身熔化的续章——世界性的丧失从概念变成了日常体验。「社会的兴起」把家政逻辑扩张为全国规模——鲍曼记下熔解的完成态。",ev:"fw",s:2},
{f:"arendt_vita",t:"sennett_corrosion",type:"coupling",label:"无行动的生涯",m:"塞内特的品格腐蚀记录短期化劳动如何毁掉「谁」的显现条件：没有持久工作、没有连续叙事，人无法在履历中留下「行动」的痕迹。阿伦特的三分给这个诊断一个骨架：被腐蚀的是工作（造耐久）与行动（在众人中开新局），剩下的只有劳动（循环保命）——短期漂移的人生里无行动可言，品格腐蚀=行动能力的物质条件被撤。被腐蚀的是工作与行动两个位，剩下的只有循环保命。",ev:"fw",s:2},
{f:"arendt_natality",t:"adorno_auth",type:"tension",label:"人格vs情境",m:"阿多诺团队的权威人格把法西斯倾向解释为被养育写入的人格结构——有F量表可测的易患体质。阿伦特的艾希曼报告给出相反归因：恶的平庸性来自情境中的「无思」——不是人格深度而是判断力的缺席，恶像真菌一样在表面蔓延。人格论与情境论的世纪对峙：权威人格找的是「哪种人」，平庸之恶找的是「哪种状态」。Stangneth的档案研究让这场人格-情境对峙至今未决。",ev:"fw",s:3},
{f:"weber_iron",t:"arendt_natality",type:"coupling",label:"铁笼产官僚",m:"韦伯的理性化预言铁笼：科层制把人变成功能配件。阿伦特的艾希曼正是铁笼的产物样本：满脑子官样文章、无法从他人立场思考的公务员——理性化的官僚制批量生产不需思考的执行官。一个给结构（铁笼）、一个给结构里人的形态（无思）——平庸之恶是铁笼的人格面相：恶的平庸性就是理性化的人性成本。铁笼与无思是同一装置的结构端与主体端。",ev:"fw",s:2},
{f:"arendt_natality",t:"foucault_disc",type:"coupling",label:"无思×自监视",m:"福柯的规训讲身体如何被全景敞视驯顺；阿伦特的「无思」补上灵魂那一半：不只身体被规训，判断力本身可以被套话替代——艾希曼的罪恶不靠强制而靠拒绝思考。两条路径合观：现代权力既从外部制造驯顺身体、也从内部抽空思考能力——官僚制的极致不是压迫而是让「想」变得不必要。诞生性则是她对必然性政治留下的解毒剂——每个新来者都带着开新局的可能。",ev:"fw",s:2},
{f:"marx_class",t:"thompson_ep",type:"genealogy",label:"自在→做成",m:"马克思留下自在阶级/自为阶级的公式：客观位置产生利益，利益再转化为意识。汤普森把公式落实为经验与文化：阶级不是物而是历史事件，「是一批人在共同经历中感受到并表达出来的关系」——工匠读潘恩、建卫理会、结社，把自己做成工人阶级。自在到自为的跳跃不靠自动机制，靠的是文化媒介里的共同经验。《英国工人阶级的形成》九百页就是这条谱系的兑现。",ev:"fw",s:3},
{f:"thompson_ep",t:"willis",type:"coupling",label:"英国双线",m:"汤普森写工匠如何把阶级「做成」；威利斯写工人子弟如何把阶级「再做成」——lads看穿文凭许诺却以男子气概主动选入劳工位。两书是英国文化马克思主义的双峰：一个证明工人参与自身形成、一个证明再生产也靠工人自己的文化能动性——「不是被放上去而是自己走进去」是两人的共同发现，只是一个讲形成、一个讲复制。这是民族志传统内部最整齐的代际接力。",ev:"fw",s:3},
{f:"thompson_ep",t:"scott_moral",type:"genealogy",label:"道德经济正传",m:"汤普森在粮食暴动研究里造出「道德经济」一词：暴动不是饥饿痉挛而是民众对正当价格的规范性判决。斯科特的道义经济直接继承：东南亚农民抗税的安全底线逻辑——生存伦理先于利润理性。一个是十八世纪英格兰的面包暴动、一个是二十世纪缅甸的抗税——道德经济从概念原型长成农民研究的分析轴心。《农民的道义经济》的谱系页码直接通向汤普森。",ev:"fw",s:2},
{f:"thompson_ep",t:"althusser",type:"tension",label:"经验vs结构",m:"汤普森对阿尔都塞的论战是英国经验论对法国结构主义的总决裂：阿尔都塞的询唤说主体被意识形态结构召唤而成；汤普森的《理论的贫困》反击「经验」不可被结构消化——人在共同经历中感受并表达，文化不是残余而是媒介。阶级形成的历史学对阵主体召唤的理论机器——「结构是否给经验留了位置」是这场对峙至今未决的核心。《理论的贫困》是这场论战的正面文本。",ev:"fw",s:3},
{f:"hobsbawm",t:"anderson_imagined",type:"coupling",label:"想象的车间",m:"安德森的想象的共同体讲民族如何被认知建构：印刷资本主义让百万陌生人同步想象。霍布斯鲍姆的传统的发明给想象补上制作车间：苏格兰裙、加冕排场、国庆日是被批量发明的仪式硬件——想象的认知结构需要仪式与谱系的物质载体。两书互相引用不是巧合：认知地图与仪式生产是民族建构的两条生产线。1870-1914是传统量产高峰期——民族国家需要公民认同。",ev:"fw",s:3},
{f:"hobsbawm",t:"gramsci",type:"coupling",label:"发明的常识",m:"葛兰西的文化霸权说统治靠常识的生产：让支配被体验为自然。被发明的传统正是常识生产的史学证据——国庆、国歌、纪念碑把「民族连续体」焊进日常景观，使国家的新秩序被体验为古老秩序。一个是霸权机制的政治理论、一个是霸权工序的历史案例库：合法性的制造车间把政治需要包装成文化传承。发明的传统也能被被支配者挪用为抵抗资源——五一节即证。",ev:"fw",s:2},
{f:"hobsbawm",t:"gillis",type:"coupling",label:"家庭也发明",m:"霍布斯鲍姆证明公共传统是被发明的；吉利斯把这个发现推进家庭私域：维多利亚时代的家庭仪式——圣诞、周日晚餐、蜜月——同样是被发明的传统，把现代核心家庭包装成永恒形态。从国家到客厅，同一机制在不同尺度运转：「自古以来」总是近代工程——发明传统是合法化的通用技术，公私两域通吃。Gillis把这一发现从公共领域推进到客厅。",ev:"fw",s:2},
{f:"gramsci",t:"burawoy",type:"genealogy",label:"霸权下车间",m:"葛兰西的文化霸权说同意是在市民社会里制造的：学校、教会、媒体把秩序内化为常识。布洛维把霸权从市民社会下沉到劳动过程：赶工游戏、内部劳动市场、内部国家三层装置在车间里生产同意——工人参与游戏即默认规则，剩余价值的榨取被博弈的乐趣遮蔽。《制造同意》明言要把葛兰西落到机器旁：霸权的发动机不在讲坛在打卡机。",ev:"fw",s:3},
{f:"burawoy",t:"bowlesgintis",type:"coupling",label:"同意×对应",m:"鲍尔斯与金蒂斯的对应原理说学校复制工厂所需的人格：服从、守时、外部奖惩。布洛维补上工厂端的真相：被复制的不是服从而是同意——赶工游戏让工人自愿超额，因为游戏把剥削包装成对抗定额员的竞技。学校教「愿意来上班」、车间教「愿意多干活」——对应的两端都是同意的生产装置，只是一个在课堂、一个在机床。对应原理的制度面在车间里被补上同意这一层。",ev:"fw",s:2},
{f:"burawoy",t:"willis",type:"coupling",label:"同意两版本",m:"威利斯的lads与布洛维的机床工是工人能动性的两种形态：lads用反学校文化公开抵抗，抵抗本身走回劳工位；车间工用赶工游戏局部博弈，博弈本身遮蔽了剥削。一个说抵抗即再生产、一个说参与即同意——两本民族志共享同一反直觉：工人不是被骗进再生产，是在有尊严的游戏与抵抗中亲手参与它。Donald Roy三十年前在同一车间的前史是这条边的民族志锚点。",ev:"fw",s:3},
{f:"marx_fetish",t:"polanyi",type:"genealogy",label:"物化历史化",m:"马克思的商品拜物教是哲学诊断：物与物的关系遮蔽人与人的关系。波兰尼把这个批判历史制度化：劳动力、土地、货币本非商品，被虚构为商品的十九世纪就是物化的政治经济学版本——人被撕出社会保护母体、自然被压成价格。拜物教从观念批判变成历史运动分析：虚拟商品化是拜物教在国家工程层面的实现。斯宾汉姆兰制度是其微观标本。",ev:"fw",s:2},
{f:"polanyi",t:"standing",type:"coupling",label:"去嵌入=不稳",m:"波兰尼的双向运动说市场每扩张一步社会就自我保护——前提是劳动力曾被「嵌入」过。斯坦丁的不稳定无产者是去嵌入的当代后果：劳动力再商品化推进到新深度，旧保护（工会、终身雇、福利）被拆、新保护未建——不稳定化的深度由保护反应的迟到程度决定。一个是宏观史的机制、一个是机制的当代人口。precariat就是双向运动中保护反应尚未到位的人群形态。",ev:"fw",s:3},
{f:"polanyi",t:"human_capital",type:"tension",label:"人不是资本",m:"人力资本把人读作资本存量的携带者：技能=可折旧资产，教育=投资。波兰尼的虚拟商品批判指出这正是完成形态的商品化：劳动力是人的活动，把它读作「资本」就是十九世纪乌托邦工程的词汇学胜利——人先被虚构为商品、再被升级为人力资本。反对的不是教育投资而是这个读法本身：被资本化的人就从社会母体里被撕出来了。这条张力是本图谱关于「人能否被资本化」的正面交锋。",ev:"fw",s:3},
{f:"marx_class",t:"harvey",type:"genealogy",label:"原始→持续",m:"马克思的原始积累是资本主义的历史起点：圈地、殖民、暴力剥离。哈维的剥夺式积累把它从史前史改写为持续机制：当代积累越来越不靠剥削剩余价值而靠直接占有——私有化、金融化掠夺、危机操纵、国家向上再分配。剥削与剥夺不是替代关系而是双引擎：原始积累的「原始」被划掉，成了资本主义的常规模式。《新自由主义简史》把剥夺写成当代积累的常规模式。",ev:"fw",s:3},
{f:"harvey",t:"brown_demos",type:"coupling",label:"底稿相通",m:"布朗的取消德谟诊断经济理性殖民政治主体：人被铸成自我企业家、公民被冲垮。哈维给同一过程政治经济学底稿：1970年代危机后新自由主义把「自由」话语锻造成阶级工程——目标是重建上层积累条件而非解放市场，结果是顶层份额全线回升。一个写民主主体的被取消、一个写取消者的积累策略——同一场阶级工程的政治与经济两个切面。",ev:"fw",s:2},
{f:"polanyi",t:"harvey",type:"genealogy",label:"去嵌入波段",m:"波兰尼的双向运动是二十世纪版：市场乌托邦扩张→社会自我保护。哈维的剥夺式积累是它在新自由主义波段的重演：去嵌入从工厂法时代转入私有化与金融化时代——公共资产被收割、危机被操纵成积累时机，保护反应（社保、监管）被第二波市场扩张拆掉。同一个双向运动在两个世纪的转速对比：保护装置还没建好，下一波去嵌入已到。",ev:"fw",s:2},
{f:"harvey",t:"lazzarato",type:"coupling",label:"金融化主体",m:"哈维说时空修复把过剩资本倒进时间——债务、期货把危机推迟并外移；拉扎拉托的负债人补上这过程的主体面：债务不只转移风险，它生产一种新人——生命全程被还款计划结构化、未来被预先抵押。一个是资本的时空操作、一个是被抵押者的主体形态——时空修复在个体身上留下的不是债务余额而是负债身份。债务主体性让「修复」落到了月度账单上。",ev:"fw",s:2},
{f:"anderson_imagined",t:"marx_class",type:"tension",label:"民族盖阶级",m:"马克思问工人为何不联合；安德森给出难堪答案：他们宁可为民族死、不为阶级战——民族想象关联语言的纯真与死亡的终极意义，阶级政党总带利益计较的气味。这不是否定阶级而是阶级叙事必须吞下的反向证据：在情感深度上，民族系统性地胜过阶级——想象的共同体回答了剥削论最难处理的忠诚问题。人口普查、地图、博物馆补完了这个回答的工艺部分。",ev:"fw",s:2},
{f:"anderson_imagined",t:"gramsci",type:"coupling",label:"常识的民族版",m:"葛兰西的霸权讲常识的生产让秩序自然化；安德森的共同体讲民族如何用印刷资本主义把「同属一国」写进每日晨读——同步想象是常识生产最成功的形态。报纸、普查、地图、博物馆是装置，民族是产出——霸权的常识车间在民族维度运转得最彻底：连「为人民而死」的情感都被常识化。「同质的空洞时间」正是常识被批量生产的时间格式。",ev:"fw",s:2},
{f:"foucault_disc",t:"deleuze_guattari",type:"genealogy",label:"规训→调制",m:"福柯的规训社会是封闭环境的序列：家庭-学校-军营-工厂-监狱，人从一堵围墙转移到下一堵。德勒兹的控制社会短文宣布围墙熔化：人不再被禁锢而是被调制——密码门禁、持续考核、永不结束的培训、可分割的债务；个人变成dividual（数据切片）。他自己说这是福柯的续章：规训的模子换成调制的键盘——监禁的旧语法被改写成永不结案的实时流。",ev:"fw",s:3},
{f:"deleuze_guattari",t:"lazzarato",type:"genealogy",label:"负债人源出",m:"德勒兹写下那句最阴郁的判词：「人不再是被禁锢的人，而是负债的人。」拉扎拉托的《负债人》把这句扩成整本书：债务是当代主体的核心装置——债权人-债务人关系先于一切契约、把未来预先抵押。控制社会给命题、负债人给展开：债务不是经济事实而是治理技术——合著关系让这条谱系有书信级而非诠释级的直接性。「调制」的最锋利工具就是把人变成永远还不完的人。",ev:"fw",s:3},
{f:"deleuze_guattari",t:"han",type:"coupling",label:"无禁令社会",m:"德勒兹的控制社会说服从不再需要围墙与禁令——人被持续调制。韩炳哲的功绩社会是同一诊断的德语版：功绩主体不被禁止而被要求——「你能」比「你必须」更彻底地剥削，自我剥削取代了外部规训。无禁令的控制、无止境的自我优化——两位都在说：当约束内化，自由话语本身就是最高效的锁链。韩炳哲的功绩主体正是控制社会的当代形态。",ev:"fw",s:2},
{f:"marx_fetish",t:"zizek",type:"genealogy",label:"拜物教拉康化",m:"马克思的拜物教公式是「他们对此一无所知，但他们正在做」；齐泽克把它倒转：今天的犬儒主体是「他们非常清楚，但仍然做」——意识形态从信仰层面搬到实践层面，距离本身就是机制。商品的鬼魂从「无知的误认」升级为「清醒的共谋」：幻象不遮蔽现实而是建构现实本身——拜物教的拉康化重读让批判失去假面摘除的旧武器。齐泽克1989年英文处女作即以此为题眼。",ev:"fw",s:3},
{f:"althusser",t:"zizek",type:"genealogy",label:"询唤→幻象",m:"阿尔都塞的询唤说意识形态把个体召唤成主体；齐泽克用拉康重写这条生产线：主体被幻象认同缝合——崇高客体（领袖、民族、犹太人形象）是撑住社会对抗的支点，享乐而非信念是粘合剂。询唤是结构主义的版本、幻象是拉康的版本——意识形态批判的对象从「错误意识」移向「实在界里撑住我们的东西」。师生都在法国结构主义内部，只是引擎换成了拉康。",ev:"fw",s:2},
{f:"zizek",t:"fisher",type:"genealogy",label:"犬儒→反身",m:"齐泽克论证犬儒距离是意识形态的当代形态：知道但照做，批判性距离已被体制预先收编。费舍尔的资本主义现实主义与反身性无能把这个机制写进英伦青年文化：明知没有替代方案，所以更卖力地演——「知道但无用」正是犬儒运作的大众版。齐泽克给哲学装置、费舍尔给它的课堂与病房民族志——反身性无能是犬儒理性的青年形态。Fisher把hauntology写进课堂与病房——这条谱系几乎可指认。",ev:"fw",s:3},
{f:"zizek",t:"honneth",type:"tension",label:"承认vs实在",m:"霍耐特把社会冲突的道德语法锚定在承认的失败上：伤害经验可指明、可疗伤。齐泽克的拉康路线拒绝这个地基：社会对抗的硬核是不可符号化的创伤实在——幻象不是承认的失败而是实在界的补丁，承认叙事本身就是一种幻象。两种左派语法：一个要修复承认秩序、一个说秩序本身建立在不可修复的裂口上——「伤」与「洞」是两种地基。",ev:"fw",s:2},
{f:"althusser",t:"ranciere",type:"tension",label:"师生决裂",m:"朗西埃对老师阿尔都塞的决裂点是解放的逻辑：阿尔都塞式结构分析要专家替无知者看清意识形态——「被解放者需要被启蒙」本身已是治安逻辑，把知识差距写进解放前提。朗西埃的平等公理相反：平等不是目标而是前提预设——不是努力达到平等而是假定并验证它，工人挪用夜晚写诗就是验证。解放不是被给予的而是被上演的。《歧见》把决裂理论化：平等是前提预设而非追求目标。",ev:"fw",s:3},
{f:"ranciere",t:"honneth",type:"tension",label:"承认vs公理",m:"霍耐特说社会冲突的语法是争取承认：伤害驱动斗争，承认可被给予也可被收回。朗西埃的歧见换了语法：政治不是求承认而是把「错误」演出来——无份者以平等公理登场，不是要求被承认为合格成员而是展示治安秩序的分配本身就是错。斗争为承认 vs 斗争为验证公理——两种道德语法给同一批冲突写不同的剧本。劳工的夜晚档案与承认斗争共享同一批行动者。",ev:"fw",s:2},
{f:"ranciere",t:"willis",type:"coupling",label:"拒绝被定义",m:"朗西埃的工人夜晚档案：白天做工、晚上写诗办报的工人拒绝「工人的位置」——挪用不属于他们的时间，解放的原型就是拒绝被位置定义。威利斯的lads是同一直觉的反面教材：他们也拒绝位置（学校的位置），却用拒绝走进另一个位置（劳工位）。一个给解放的原型结构、一个给它的失败变体——拒绝被位置定义不一定逃得出位置。",ev:"fw",s:2},
{f:"foucault_gov",t:"negri_hardt",type:"genealogy",label:"生命政治生产",m:"福柯的生命政治说权力开始管理生命本身：人口、健康、再生产成为治理对象。哈特与奈格里把这个诊断升级为生产方式理论：非物质劳动——生产信息、符号、情感、协作——成为霸权形式，生产的对象就是社会本身；剥削不再只榨取工作日剩余，而是征用整个协作网络即「共同性」。福柯管理生命的清单在这里变成资本主义的生产资料。生命政治从治理清单升格为资本逻辑的引擎。",ev:"fw",s:2},
{f:"negri_hardt",t:"berardi",type:"coupling",label:"意大利双联",m:"奈格里与贝雷塔同出意大利自治主义传统、几乎同期同调：《帝国》说非物质劳动征用整个协作网络，《灵魂在工作》记认知劳动如何把灵魂本身变成生产资料——抑郁、焦虑、自杀是劳动征用生命的症状回执。一个给帝国的宏观结构、一个给被征用者的精神病理——自治主义的宏观诊断与临床读数在同一批工人身上合拢。Berardi的认知劳动诊断与《帝国》同期同调、同出自治主义。",ev:"fw",s:2},
{f:"negri_hardt",t:"lazzarato",type:"coupling",label:"债务同伙",m:"奈格里与拉扎拉托是同一理论星丛的伙伴：帝国说剥削征用共同性、负债人说债务抵押未来——两人合写过债务政治。非物质劳动的协作网络需要新装置来锁定：债务正是把逃逸线缝回帝国的方式——你跑不掉因为你欠着。共同性的征用与负债人的抵押是同一控制工程的两只手：一只抓生产、一只抓未来。合著关系使这条耦合几乎是自我引证级的。",ev:"fw",s:2},
{f:"negri_hardt",t:"gramsci",type:"tension",label:"阵地战还在吗",m:"葛兰西的文化霸权与阵地战预设民族-国家战场：霸权在市民社会里争夺、阵地可攻可守。帝国说这个战场已被平滑空间消解：主权去中心化、无内外，找不到可夺的冬宫也找不到可围的市民社会——诸众只能在网络里找逃逸线。最深的分歧是地理学：阵地战还存不存在？如果帝国无中心，葛兰西的整个战略语法都需要重写。帝国的平滑空间里没有冬宫可夺。",ev:"fw",s:2},
{f:"marx_fetish",t:"derrida",type:"genealogy",label:"幽灵扶正",m:"德里达把《资本论》开篇的幽灵修辞扶正为概念：幽灵性——既不在场也不缺席，以纠缠的方式使时代脱节。拜物教是商品的鬼魂舞蹈，《马克思的幽灵》是把鬼魂从隐喻升为存在论：继承马克思的不是教义而是「无弥赛亚的弥赛亚性」——对正义的等待结构。解构在这里不是拆毁而是招魂：把被唯物化掉的幽灵还给马克思。1989年后福山宣布历史终结，这本书是德里达的作答。",ev:"fw",s:2},
{f:"derrida",t:"fisher",type:"genealogy",label:"被取消的未来",m:"德里达的幽灵性说：幽灵使时代脱节——过去未安息、未来已欠债。费舍尔把它展开为「被取消的未来」的文化政治学：资本主义现实主义最大的损失不是现状而是曾经可能的文化未来——七十年代的乌托邦余温在二十一世纪连想象都被没收。德里达给幽灵的形式逻辑、费舍尔给幽灵出没的具体现场——hauntology从哲学概念变成了流行文化的诊断词。",ev:"fw",s:2},
{f:"derrida",t:"habermas",type:"tension",label:"解构vs重建",m:"哈贝马斯的生活世界殖民化仍保有规范方案：交往理性可修复系统对生活世界的侵占。德里达对一切规范重建保持根本不信任：解构之所系是不可解构的正义——「无弥赛亚的弥赛亚性」是等待不是纲领，正义永欠而不可兑现为制度蓝图。一边是修复理性工程的方案、一边是拒绝封顶的欠债结构——九十年代批判理论最深的路线分歧。制度蓝图 vs 永欠结构，是批判理论的两种时间性。",ev:"fw",s:2},
{f:"schmitt",t:"agamben",type:"genealogy",label:"决断→常模",m:"施密特的主权定义是决断例外状态之人：主权者在规范失效时刻悬置法律。阿甘本与他进行了整本书的对话——把例外从危机决断改写为治理常模：例外状态常态化、营地成为现代政治的nomos，主权不再在紧急时刻显身而在日常里持续生产赤裸生命。决断论是一次性事件，例外状态是常驻结构——阿甘本把施密特的主权瞬间拉长成了背景辐射。",ev:"fw",s:3},
{f:"schmitt",t:"habermas",type:"tension",label:"决断vs商谈",m:"施密特说政治的本质是敌我区分——商谈与中立化恰是政治性的死亡，自由主义的无限讨论是在逃避决断。哈贝马斯的交往行动理论把政治性建立在商谈理性上：无支配对话是正当性的唯一来源。这是政治性的两种本体论死结——一个要决断的强度、一个要商谈的普遍性，魏玛的幽灵与法兰克福的方案在这条边上至今未和解。决断的强度与商谈的普遍性互不相容。",ev:"fw",s:3},
{f:"schmitt",t:"brown_demos",type:"coupling",label:"同诊断异阵营",m:"施密特1920年代警告：自由主义用经济与伦理消解政治——中立化是政治性的死。布朗近百年后从对立阵营给出同构诊断：新自由主义的经济理性取消政治主体——公民变成资本，决断被审计取代。一个是右翼法学家、一个是左翼批判理论家，诊断却惊人平行：政治主体被经济化过程注销——「取消德谟」是「政治之死」的当代续写。",ev:"fw",s:2},
{f:"foucault_gov",t:"agamben",type:"genealogy",label:"使人死",m:"福柯的生命政治是「使人活」：权力管理人口、健康、生育——生命成为投资对象。阿甘本把这个分析推到反面：主权的秘密不是使人活而是使人死——在例外状态中生产赤裸生命，可被杀而不可献祭。生命政治的光明面是管理与照护，黑暗面是收容与排斥——从「使人活」到「使人死」是同一权力机制的两档。homo sacer的形象是这个机制的原初签名。",ev:"fw",s:3},
{f:"agamben",t:"bauman",type:"coupling",label:"废弃生命",m:"鲍曼的有缺陷的消费者是消费社会里的废弃品：不合格买家被系统判定无用途。阿甘本的赤裸生命是它的主权论底稿：被法律以「可被杀」方式包含的排斥——废弃不只是市场判定更是例外状态的生产物。一个是社会学对废弃人口的民族志、一个是政治哲学对废弃的范畴化——废弃的生命在两套词汇里指向同一批人。营地不是历史异常而是现代政治的nomos。",ev:"fw",s:2},
{f:"agamben",t:"desmond",type:"coupling",label:"驱逐=微例外",m:"阿甘本的例外状态说主权把生命悬置于法外之地：营地是范型。驱逐法庭是例外状态的微型日常版本：房客在法庭走廊里被悬置——有程序之名、无保护之实，住所权在瞬间被移出法律覆盖。赤裸生命不需要集中营才产生：每一次扫地出门都是一次小规模例外宣告——驱逐民族志因此是例外论的微缩胶片。现代政治的nomos在住房法庭里轮班。",ev:"fw",s:2},
{f:"giddens_self",t:"beck_risk",type:"coupling",label:"英德双联",m:"吉登斯的反思性自我工程与贝克的风险社会-个体化是同代孪生命题：都说晚期现代把「我」从给定身份里抛出，脱域机制与制度反思性使自我成为必须续写的叙事——人生从被给定的命运变成自己负责的工程。一个写传记的修订技术、一个写风险的个体化——英德两路在「自我成工程」上同步：反思性传记就是风险社会里个人化生存的作业面。",ev:"fw",s:3},
{f:"giddens_self",t:"rose",type:"tension",label:"自由or治理",m:"吉登斯把反思性工程读作自由条件：治疗文化与自助书是现代人修订自我的文具。罗斯的治理灵魂读同一堆材料得出治理装置：psy专业把「心理健康」变成自我优化指令——你以为在修自己，其实在执行治理。同物异读是本图谱的经典张力：自我工程既是自由的技术也是被治理的接口——反思性到底是解放工具还是治理通路，取决于谁来写说明书。",ev:"fw",s:3},
{f:"giddens_self",t:"mcadams",type:"coupling",label:"传记可测",m:"吉登斯说自我是反思性工程：传记是被持续修订的叙事。麦克亚当斯的生命故事模型把这个哲学命题心理测量化：叙事同一性成为人格第三层——救赎序列、污染序列可被编码、计分、追踪。反思性自我工程在生命故事访谈里获得了实证形态：「我」的续写工程不再只是本体论，成了可被访谈法取样的叙事材料。英语世界两个反思性叙事传统在此合拢。",ev:"fw",s:2},
{f:"giddens_self",t:"bourdieu",type:"tension",label:"反思余裕",m:"吉登斯预设行动者有反思余裕：自我是可以修订的工程，约束可被反思穿透。布迪厄的惯习说余裕本身是分配的：惯习的惯性让反思能力按位置配给——「我」能反思「我」到什么程度，恰是阶级写入的深度。行动者到底有多少反思余裕，是两人本体论的分水岭——这条边是全图关于「能动性」争端的正面交锋点。反思能力的阶级分布是这个张力的实证支点。",ev:"fw",s:3},
/* ══ 存在主义 exi ══ */
{f:"nietzsche",t:"scheler",type:"genealogy",label:"怨恨解剖",m:"尼采在《道德谱系学》里命名怨恨：奴隶道德把无力报复升华为价值重估。舍勒1912年给它现象学解剖学——怨恨不是嫉妒而是「无力的报复」在体内发酵：冲动被压抑不能外发，就结晶为价值错觉，把高贵读成傲慢、成功读成运气。他还反转了尼采的结论：怨恨恰恰否定基督教价值而非其来源——同一概念两代用法，一个指控、一个辩护。",ev:"fw",s:2},
{f:"scheler",t:"sennettcobb",type:"coupling",label:"隐痛=尊严税",m:"舍勒的公式：怨恨产量与「应得感-可得性」裂缝成正比——人人平等的许诺碰上处处不平等的兑现，就是怨恨最大工厂。塞内特与科布的隐性伤害正是这条裂缝的田野记录：工人要证明自己配得上，尊严变成须不断偿付的税。一个是现象学的裂缝公式、一个是民族志的尊严账目——阶级隐痛就是应得与可得之差的日常形态。裂缝越大自尊偿付越频繁——尊严经济学的计量单位。",ev:"fw",s:2},
{f:"scheler",t:"sandel",type:"coupling",label:"绩优=裂缝机",m:"桑德尔的绩优暴政论证meritocracy系统性生产两件事：赢家傲慢与输家屈辱——「你应得你的位置」既是许诺也是判决。舍勒半个世纪前已给出产量函数：讲人人可上升却处处分层的社会，把应得-可得裂缝开到最大，怨恨产量因此最高——平等许诺反而增产怨恨。绩优制不是偶然的副作用而是怨恨的流水线设计。舍勒的产量函数解释了为什么绩优制社会怨恨最盛。",ev:"fw",s:3},
{f:"scheler",t:"lamont",type:"coupling",label:"边界=升华",m:"拉蒙的工人道德边界研究记录：劳工用「我们更正直、他们不真」的划线重建尊严——把不可得的财富贬低为不值的品格。舍勒的怨恨现象学给这种划界一个更深读法：价值错觉的温和形态——把高价值重估为低，是无力的报复在道德语言里的升华。一个是民族志记录到的道德语法、一个是现象学揭示的生成机制——边界划的是怨恨被驯化后的形状。",ev:"fw",s:2},
{f:"jaspers",t:"heidegger",type:"genealogy",label:"墙→向死",m:"雅斯贝尔斯1919年提出边界处境：死亡、斗争、痛苦、罪责是无法绕道的墙，撞墙时日常外壳碎裂、生存被迫显形。海德格尔把这个处境结构改写为基础存在论：先行到死不是偶发撞击而是此在的常驻筹划——向死而生把墙从外部事件搬进生存结构。海德格尔本人承认受惠：边界处境是图纸，向死而生是把图纸浇进了此在的地基。《哲学》1932年的展开本被存在论工程整体吸收。",ev:"fw",s:2},
{f:"jaspers",t:"yalom",type:"genealogy",label:"处境→关怀",m:"雅斯贝尔斯的边界处境清单——死亡、痛苦、罪责、偶然——与亚隆的四大终极关怀（死亡、自由、孤独、无意义）是明显的谱系重叠：存在主义心理治疗把哲学处境临床化为可工作的焦虑源。雅斯贝尔斯说撞墙是哲学觉醒的契机，亚隆说对终极关怀的觉察是治疗的工作面——从生存哲学到治疗室，墙被改装成诊断坐标。四关怀清单与边界处境清单的重叠不是巧合。",ev:"fw",s:2},
{f:"jaspers",t:"desmond",type:"coupling",label:"驱逐=强制撞墙",m:"雅斯贝尔斯说边界处境是外壳碎裂的瞬间——但谁是撞墙的人并非均匀分布。德斯蒙德的驱逐民族志展示了阶级化的强制边界化：扫地出门把穷人的住所、学校、社群一次性撤走，是制度批量生产的「撞墙」。哲学上墙是存在觉醒的机会，社会学上墙是位置的附属品——缓冲垫的有无决定了撞墙对谁是契机、对谁是废墟。哲学家的墙与社会学家的驱逐令指向同一个破门瞬间。",ev:"fw",s:2},
{f:"jaspers",t:"ehrenreich",type:"coupling",label:"缓冲变薄",m:"雅斯贝尔斯的边界处境预设人会「撞墙」；中产阶级的日常工程恰恰是买保险、储蓄、攒文凭来延迟撞墙。埃伦赖希的坠落恐惧描述缓冲变薄后的预支性眩晕——还没撞就先眩晕，整个阶层的存在性焦虑是边界处境的慢性低烧版本。雅斯贝尔斯给撞墙的现象学，坠落恐惧给撞墙前的阶级预防医学——中产购买的其实是「延迟撞墙」的期权。缓冲的厚度本身就是阶级资产。",ev:"fw",s:2},
{f:"buber",t:"levinas",type:"genealogy",label:"对称→高位",m:"布伯的我-你说真实生活在相遇：双向、相互、在场的「之间」。列维纳斯继承相遇本体论但拆掉其对称性：他者不是平等的对话伙伴而是高位者——脸发出「你不可杀」的命令，我的责任先于任何互惠。从「之间」到「不对称」，是相遇伦理学的内部修正：布伯把关系写成圆舞，列维纳斯指出舞伴里有一个永远站得更高、我永远欠着。列维纳斯认为他者其实是不对称的高位者——我永远欠着。",ev:"fw",s:2},
{f:"buber",t:"hochschild",type:"coupling",label:"微笑=我-它",m:"布伯的我-它世界是他者被化约为功能与用途的通道；情绪劳动正是我-它的职业化版本：空乘的微笑、服务员的问候是把他人彻底工具化的付费演出——连自己的情感都被变成它。霍克希尔德记录了管理的精妙：公司不只购买你的动作，还购买你的内心做工——相遇的反面在服务业流水线里被批量排班。布伯给的是本体论词汇，霍克希尔德给的是它的田野运作。",ev:"fw",s:2},
{f:"buber",t:"goffman",type:"coupling",label:"前台=它化",m:"戈夫曼的拟剧论说前台表演是互动的必要技术：我们都得演。布伯的二分给了这种演技一个存在论名字：前台是被制度化的它-关系——把他人先当观众与角色处理，「之间」被台本预先收编。污名则是它化的失败案例：当观众看穿表演，表演者被还原成一件被审视的物。互动秩序的表面中立底下，是我-它与我-你的持续结算。布伯给的是本体论词汇，戈夫曼给的是它的田野运作。",ev:"fw",s:2},
{f:"schutz",t:"bergerluckmann",type:"genealogy",label:"库存→nomos",m:"舒茨的库存知识说日常的理所当然是被预制好的：处方知识与类型化把手头世界先验组织。他的学生伯格与卢克曼把这个微观构成学扩成全本理论：《实在的社会建构》追问社会秩序如何被体验为客观实在——nomos。上游是现象学的「手头」、下游是社会学的「建构」——理所当然不是中性的，它是被分配、被合法化、被代代相传的预制实在。",ev:"fw",s:3},
{f:"schutz",t:"lareau",type:"coupling",label:"处方差异",m:"舒茨的库存知识是阶级分配最不均的资源：怎么跟老师谈判、怎么填表、怎么对机构提要求——这些处方知识在中产家庭是常备库存，在劳工家庭是稀缺品。拉鲁的协作培养正是处方知识的传递现场：中产父母示范机构操作，孩子继承的是「手头知识库」而非单纯价值。一个给「理所当然如何被构成」的现象学、一个给「谁的理所当然」的民族志。",ev:"fw",s:3},
{f:"schutz",t:"bourdieu",type:"coupling",label:"手头vs身体",m:"舒茨说日常世界由手头知识预制；布迪厄的惯习说同一预制写得更深——进入身体而非口袋，成为知觉与鉴赏的生成机制。两者描述同一现象的深浅两层：库存知识是可陈述的处方，惯习是说不出口的操作系统。舒茨先讲清「想当然」的构成机制，布迪厄补上它的权力硬度——想当然的不是中性知识，是被位置写进身体的注定感。舒茨刻意悬搁权力——谁的知识算库存留给后人。",ev:"fw",s:2},
{f:"levinas",t:"sartre",type:"tension",label:"责任先于自由",m:"萨特说人是被判自由：我的选择先于一切、为一切负责——自由是第一本体论。列维纳斯把整个排序倒转：我对他者的责任先于我的自由，在我选择之前脸已发出「你不可杀」——伦理先于本体论。一边是从自我出发的无限自由、一边是从他者出发的无限责任——二十世纪法国哲学最深的内部对峙：主体的原罪不是被抛，而是先占了他者的位置。",ev:"fw",s:3},
{f:"levinas",t:"honneth",type:"coupling",label:"脸→承认",m:"列维纳斯说脸是伦理事件：不可化约、发出命令、我要为没做的事负责。霍耐特的承认理论把这个现象学伦理转成社会冲突语法：承认的失败（无视、污名、剥夺权利）为何伤人，深处是列维纳斯式的——人被拒绝进入「之间」。一个给道德经验的现象学底稿、一个给底稿的制度化版本：被无视者的道德语法由列维纳斯奠基、由霍耐特翻成政治。",ev:"fw",s:2},
{f:"levinas",t:"bauman",type:"genealogy",label:"伦理译本",m:"鲍曼的《后现代伦理学》几乎是列维纳斯的社会学译本：现代性的官僚-市场装置系统性地把他者它化——距离化、对象化、范畴化，把「脸」磨平成案例号；后现代的任务是恢复不被中介的相遇责任。流动现代性里「有缺陷的消费者」正是这种它化的完成形态：穷人的脸不被读出伦理指控，只被读出市场失格。哲学家的脸成了社会学家的排除机制描述。",ev:"fw",s:2},
{f:"ricoeur",t:"mcadams",type:"genealogy",label:"词是他借的",m:"利科的叙事同一性把自我劈成idem（什么持续）与ipse（谁能作证），再用情节化把两者缝成一个可讲的故事。麦克亚当斯的生命故事模型公开继承了这个词——「叙事同一性」就是从利科借的：人格第三层（生命故事）正是idem与ipse在美式心理学里的可测版本。诠释学的缝合公式被操作化为故事编码——谱系直得连名词都没换。",ev:"fw",s:3},
{f:"ricoeur",t:"sennett_corrosion",type:"coupling",label:"情节化失败",m:"利科说叙事同一性靠情节化：把零散事件缝成可讲的故事。塞内特的品格腐蚀诊断的是缝合条件被拆：短期化劳动、项目制、履历漂移让人生的原材料失去连续性——不是人不会讲，是事件拒绝成情节。用利科的词：这是情节化的结构性失败，人生失叙不是叙事技巧问题而是时间供给问题——腐蚀的正是「一个」人生得以成立的材料。情节化是耗资源的工作——时间、语言储备、听众。",ev:"fw",s:3},
{f:"ricoeur",t:"maruna",type:"coupling",label:"作证=更生",m:"利科的作证（attestation）概念：自尊=对自身能力的见证——我能说、能做、能讲述、能负责。马鲁纳的救赎脚本是作证在更生者身上的工作形态：前罪犯必须把犯罪史讲成「必要的过去→觉醒→回馈」才能获得继续做人的资格——作证不是心理奢侈品而是社会准入证。利科给「谁」的哲学、马鲁纳给谁的更生版本——能被听见的讲述本身就是阶级资源。",ev:"fw",s:2},
{f:"ricoeur",t:"silva",type:"coupling",label:"替代体裁",m:"利科说叙事是自我的缝合术；席尔瓦的治疗性成年记录缝合材料短缺时的替代体裁：当救赎脚本（奋斗→成功）不可用，青年劳工改用治疗叙事（创伤→复原→成长）来维持「我的人生仍是故事」。利科给的是文体分析工具——情节化如何组织事件，席尔瓦给的是体裁的阶级配给——体裁的配给本身就是一条意义不平等通路。不同位置的人被供应不同的故事模板。",ev:"fw",s:2},
{f:"kierkegaard",t:"binswanger",type:"genealogy",label:"谱系中介",m:"齐克果的绝望辩证法把自我定义为关系与自身的关系；宾斯万格是这条线被写进诊所的中介站——他把海德格尔的此在分析搬进精神病院，绝望失衡变成「世界设计」的变窄：Ellen West的世界收窄到只剩绝食一种出口。Frankl的存在真空概念直接出自他——齐克果→宾斯万格→意义意志，是存在主义-心理学谱系上缺他不可的一环。",ev:"fw",s:2},
{f:"binswanger",t:"rollo_may",type:"genealogy",label:"译介美国",m:"宾斯万格的此在分析在欧洲是院内方法；罗洛·梅1958年主编《存在》一书把它译介到美国——存在心理学由此登陆。May继承的不只是技术（先问病人活在什么世界），还有姿态：病理不是机制故障而是存在方式的收窄。爱与意志里的魔性、意向性概念，正是宾斯万格「世界设计」的美国改写——译介本身就是谱系延续的一种形式。",ev:"fw",s:2},
{f:"heidegger",t:"binswanger",type:"genealogy",label:"挪用此在",m:"宾斯万格把《存在与时间》的生存论分析改写成精神病理学：症状之前先写存在史，病人活在怎样的世界设计里、哪些存在方式已焊死。海德格尔本人明确表示不赞成这种人类学化挪用——哲学概念被转作临床工具，是存在论的降维也是它的第一次医学变现。此在分析因此成了所有存在治疗的上游形态：用哲学框架问「病里的人活在哪种世界」。",ev:"fw",s:2},
{f:"laing",t:"winnicott",type:"coupling",label:"两假我",m:"温尼科特的假我说是为环境顺从而构筑的自体壳；莱恩的假我系统几乎是同年异源的临床版：真我退到幕后，前台派顺从的身体与人周旋——分裂越深前台越逼真幕后越荒芜。一个从婴儿观察写、一个从病房现象学写，在「防御性自体的成本」上互证：壳是为了活，但壳越成功人越空——1960年《分裂的自我》出版的同年正是假我概念成型期。两个假我概念是六十年代分裂自我的双峰。",ev:"fw",s:2},
{f:"laing",t:"standing",type:"coupling",label:"不安的物质底",m:"莱恩的本体性不安有物质前提：感到自己真实、连续、值得活，需要可预测的住所、收入与关系连续性。不稳定无产者正是批量制造本体性不安的工业：短约、无保障、无职业叙事——不确定被写进日常结构，吞没/内爆/石化三恐惧就有了阶级生产线。莱恩给不安的现象学，斯坦丁给不安的政治经济学——疯癫的「生存策略」有供应链。",ev:"fw",s:2},
{f:"laing",t:"desmond",type:"coupling",label:"驱逐→石化",m:"莱恩说本体性不安的三恐惧之一是石化：被他人变成一件东西——这几乎是我-它关系的临床版。驱逐法庭上的「案件化」处理正是批量石化现场：房客被读成案件号、住址、欠款额，人脸被磨平成档案。莱恩给「被变成物」的临床名，德斯蒙德给它的官僚流水线——本体性不安不是哲学奢侈品，是被制度日产的体验。Goffman的Asylums同写制度疯狂——同代共振。",ev:"fw",s:2},
{f:"antonovsky",t:"marmot",type:"coupling",label:"可管理≈控制",m:"安东诺夫斯基的SOC三成分——可理解、可管理、有意义——与白厅研究的地位综合征是同一梯度的两种读数：Marmot证明健康随公务员职级递增，控制感与自主性是核心通路；SOC证明连贯感随SES递增，GRR资源清单几乎就是阶级资产别名。一个是流行病学的梯度、一个是心理测量的梯度——「地位综合征」与「意义不平等」是同一条斜率的上下游。",ev:"emp",s:3},
{f:"antonovsky",t:"casedeaton",type:"coupling",label:"SOC崩塌",m:"凯斯-迪顿的绝望死亡记录：无大学学历的白人在自杀、酒精、药物上死亡率反向上升。安东诺夫斯基的框架给它一个心理端读法：SOC崩塌——世界不再可理解（工厂消失没人解释）、不可管理（无资源可用）、不再有意义（不值得投入）。绝望死亡是社会资源撤出后连贯感的塌方——把宏观死因翻译成主观机制。SOC量表理论上应在这条曲线上先行下滑。",ev:"fw",s:2},
{f:"elder",t:"antonovsky",type:"genealogy",label:"历程沉积",m:"埃尔德的生命历程范式说：人生轨迹是历史时机×社会联结×能动性的长期沉积。安东诺夫斯基的健康起源论是同一沉积逻辑在健康维的版本：GRR资源（金钱、自我力量、支持）在历程中积累，SOC在约30岁定型——连贯感不是人格特质而是历程的沉淀物。一个给「轨迹如何沉积」的总框架、一个给沉积物在健康上的具体形态——健康起源是历程原则的医学翻译。",ev:"fw",s:2},
{f:"frankl",t:"ryff",type:"operationalizes",label:"目的量表化",m:"弗兰克尔的意义意志原是临床与存在的宣称：人首要动机是意义。瑞夫把这个宣称变成全国样本的可计分维度：PWB六维中的「人生目的」与「个人成长」直接取法Frankl，MIDUS数据证明目的感随年龄下滑、被教育收入强烈预测、前瞻预测更低死亡率与阿尔茨海默风险——存在命题第一次有了流行病学纵贯证据链。哲学宣称被量表化后，意义不平等变成可见的阶级梯度。",ev:"emp",s:3},
{f:"ryff",t:"lachman",type:"coupling",label:"掌控互证",m:"瑞夫的环境掌控维度与拉赫曼的掌控感量表同源于MIDUS库：一个测「我能管理生活的环境」、一个测「事情掌控在我手中」——两个相邻构念在同一批全国样本里互证效度，也都呈现清晰的阶级梯度。环境掌控是PWB的实现论条目、掌控感是健康老龄化的预测因子——幸福感研究的两条产品线共用同一块数据地基，互证本身就是效度证据。",ev:"emp",s:2},
{f:"ryff",t:"erikson",type:"genealogy",label:"六维=任务",m:"瑞夫六维不是任意清单：每维对应一项发展任务——自主对自主感、积极关系对亲密、人生目的对繁衍、自我接纳对自我整合——艾瑞克森八阶段的成长任务被她改写为成年期可计分的幸福维度。谱系是设计蓝图关系：阶段论给「该长什么」，PWB给「长成了多少」——发展心理学的时间表被翻译成横截面量表，阶段任务变成连续分数。",ev:"fw",s:2},
{f:"park",t:"ptg",type:"coupling",label:"引擎给PTG",m:"PTG文献记录「创伤后成长」现象但缺机制；Park的意义建构模型正好补上引擎：全局意义（世界公正可控）被事件违反→失配即痛苦→意义建构缩小差异（同化改评估、顺应改全局）→产物是「被造出的意义」含获益感。这套框架同时容纳了PTG的批评：感知成长可能只是评估性产物而非人格变化——被造出的意义是缓解失配的工具，不必然是真成长。",ev:"fw",s:3},
{f:"park",t:"steger",type:"coupling",label:"寻求=失配",m:"Steger的MLQ「意义寻求」维度测的是人在找意义；Park的模型给了这个「在找」一个机制读法：寻求正是全局意义与情境意义失配的信号——差异本身就是痛苦，寻求是加工在运转的征候。美国样本中高寻求与抑郁相关、日本样本中寻求与成长相关的文化差异，在Park这里可读为「可接受的建构脚本」不同——失配的体验被文化供给。",ev:"emp",s:2},
{f:"park",t:"durkheim_suicide",type:"coupling",label:"集体版失配",m:"Park的全局意义崩塌在个体层是创伤后失配；涂尔干的失范是它的社会学原型：社会剧变（经济危机、快速转型）使调节欲望的旧规范失效，个体的「世界讲得通」前提集体瓦解——失范型自杀就是全局意义被结构撤走后的极端产物。一个是个体机制、一个是集体形态——「假定世界被打碎」在个人史里是事故，在历史里是失范。涂尔干的自杀类型学是最早的集体失配分类。",ev:"fw",s:2},
{f:"arendt",t:"marx_alien",type:"coupling",label:"三分修四重",m:"马克思的异化劳动四重规定诊断工人从产品、过程、类本质、同侪四面被剥离；阿伦特的劳动-工作-行动三分是公开的重写与修正：她把马克思混用的labor与work劈开——循环维生是劳动、造耐久世界是工作、在众人中开创是行动。异化在她的词汇里不只是劳动被剥夺，而是「世界的丧失」：劳动动物吞掉工作与行动，人连留痕的地方都没有。",ev:"fw",s:3},
{f:"arendt",t:"han",type:"coupling",label:"劳动动物变体",m:"阿伦特1958年预言劳动者社会：一切活动被翻译成生计与消费，行动与工作被劳动逻辑吞没。韩炳哲的功绩主体是这个诊断的晚期形态：劳动动物连外在的剥削者都不再需要——自我剥削把生计律令内化，倦怠是劳动动物的最后姿态。一个给「社会的兴起」吞噬世界的诊断、一个给吞完后主体的状态报告——劳动动物的终点站是倦怠。",ev:"fw",s:2},
{f:"arendt",t:"silva",type:"coupling",label:"劳动位失守",m:"阿伦特的三层结构预言：底层被压在劳动位——消耗性、无作品、无留痕。席尔瓦的受挫成年记录连劳动位都保不住的处境：新世代工人没有稳定劳动可异化，只能转向治疗叙事求尊严。一个是劳动-工作-行动的位序图谱、一个是位序最底端失守后的田野——「动物劳动者」在最坏情形下连可持续消耗都失去，留在位置之外。治疗叙事成了劳动位失守后的替代体裁。",ev:"fw",s:2},
{f:"arendt",t:"kohli_mayer",type:"tension",label:"三段式批判",m:"科利-迈耶的生命历程制度化把人生写成教育-工作-退休三段式——阿伦特会读出这是她诊断的制度化翻版：三段式把行动与工作压缩进「工作期」，其余时段维生化，生涯制度本身就是「社会的兴起」对vita activa的收编。她批判的不是分段的错而是它完成的倒转：人被供养成劳动动物的时序形态，行动空间在制度设计里就没有格子。",ev:"fw",s:2},
{f:"huizinga",t:"lareau",type:"coupling",label:"排程vs自发",m:"赫伊津哈的游戏判据——自愿、魔圈、非功利——正是拉鲁两种童年的差异轴：中产协作培养把游戏排程化目标化（足球课、考级、成人裁判），劳工自然成长的游戏保留自发形态（街头、混龄、无裁判）。同一件事两种形态：游戏在中产被组织成发展投资、在底层仍是「游戏的人」的原始样态——游戏精神的分布本身就是阶级地图——劳工孩子的自由游戏恰是「魔圈」的幸存形态。",ev:"fw",s:2},
{f:"huizinga",t:"winnicott",type:"coupling",label:"游戏双源",m:"赫伊津哈的魔圈与温尼科特的过渡空间是游戏概念的两个平行源头：历史学家记游戏的形式（自愿、有界、有规则、投入），临床学家记游戏的发展功能（在母亲与世界之间的第三区域，真假自我的孵化地）。一个说文明器官从游戏里长出、一个说自我从游戏里长出——魔圈是文化的、过渡空间是心理的，「不是游戏就没有文化也没有自我」是两个传统的共同底注。",ev:"fw",s:2},
{f:"huizinga",t:"bourdieu",type:"genealogy",label:"游戏感→场域",m:"布迪厄的「游戏感」与「illusio」直接借自游戏理论：场域就是一场需要被当真的游戏——幻觉投资是把赌注认作值得的前提，而谁能入场、带什么筹码早已分配。赫伊津哈说游戏自愿且游离于日常，布迪厄的场域却把人抓进游戏：你不自愿也已被计入排名。游戏的人提供形式语汇，场域理论把它社会学化——魔圈换成了有赌注分布的竞技场。",ev:"fw",s:2},
];
